INSERT INTO unit_detail (slug, title_arabic, blurb_html, edition_note, cover_key, pdf_key, published_at, source_commit) VALUES ('the-master-and-the-disciple', 'كتاب العالم والغلام', '<p>This is a work of religious instruction cast as a story: a chain of encounters between a learned man and a young seeker, built almost entirely from their talk. Its Arabic title, <em>Kitab al-Alim wa-l-Ghulam</em> — the book of the Alim and the Ghulam, the Master and the Disciple — names its two roles directly, and the dialogue between them drives the whole. Doctrine is not laid out as a treatise; it is drawn out question by question, one figure pressing and the other answering, in the manner of a Socratic exchange.</p>', NULL, 'the-master-and-the-disciple/cover.png', 'the-master-and-the-disciple/book.pdf', '2026-08-03T19:27:06Z', '2bd490a8eed27a5b8a6effb920da83e1feeb22b9');
DELETE FROM chapter WHERE slug = 'the-master-and-the-disciple';
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('the-master-and-the-disciple', 'introduction to the book', 1, 'Introduction to the Book', '<p>This is a work of religious instruction cast as a story: a chain of encounters between a learned man and a young seeker, built almost entirely from their talk. Its Arabic title, <em>Kitab al-Alim wa-l-Ghulam</em> (<span class="ar-inline" dir="rtl" lang="ar">كِتَابُ الْعَالِمِ وَالْغُلَام</span>) — the book of the Alim and the Ghulam, the Master and the Disciple — names its two roles directly, and the dialogue between them drives the whole. Doctrine is not laid out as a treatise; it is drawn out question by question, one figure pressing and the other answering, in the manner of a Socratic exchange.</p>
<p>The text is attributed to Jafar ibn Mansur al-Yaman (<span class="ar-inline" dir="rtl" lang="ar">جَعْفَر بْن مَنْصُور اَلْيَمَن</span>) and belongs to the Ismaili tradition of the early Fatimid period, the missionary teaching, the dawa (<span class="ar-inline" dir="rtl" lang="ar">دَعْوَة</span>), of roughly the tenth century. Read it as a transmitted report: the account reaches you through a narrator who relates what passed between the speakers. When an &quot;I&quot; appears inside the conversation, it is one of the characters speaking, not the author addressing you.</p>
<p>Watch the roles rather than the names. The Master here is a teacher, but the boy who arrives as a disciple travels a long road to a further, higher teacher, a shaykh, then returns home to instruct his own father and to debate a man named Abu Malik (<span class="ar-inline" dir="rtl" lang="ar">أَبُو مَالِك</span>). So &quot;master&quot; and &quot;disciple&quot; are positions that shift: the one who is taught goes on to teach, and more than one figure in these pages carries a master''s authority. Keep track of who is teaching whom in a given scene.</p>', 259);
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('the-master-and-the-disciple', 'the persian who was dead and revived', 2, '1. The Persian Who Was Dead and Revived', '<p>It has been transmitted that a number of believers, together with several of the religion''s preachers, came before one of their Masters and set a matter before him. They told him that he had set them free by reminding them of what he had made them aware of, and that this awareness had laid upon them an obligation they were now bound to discharge. That obligation, they said, was a debt of gratitude owed on three counts: gratitude for that to which he had called them, gratitude for the knowledge he had shown them, and gratitude for the work he had commanded them to do. They asked him to show them, for each of these three, what a willing person might actually do to render that gratitude. They added that, from the boundaries the religion draws, they had already grasped what was obligatory upon them and what was required of them — both what the student owes when he asks and what the one questioned owes when he answers — and that they had grasped as well, from the doctrines of the righteous and the manners of the seekers, as much as could readily be put into words.</p>
<p>The Master gave them his answer. The matter to which he had called them, he said, was the very thing he himself held in honor, and he prayed that Allah be with His servants, that He bring this matter to completion for them, and that He ennoble everyone who answers His call. Allah, he said, has appointed for the first of every thing a last, and for the last of every thing an end, and beyond every end a further end whose limit is never reached. These are the houses of the people of understanding, and their keys are remembrance. The first of these houses is affliction, the middle of them is guidance, and the last of them is piety. Whoever, then, has sought to understand how things are ordered, has stood firm upon the bounds of obligation that lie within his reach, has set his course toward guidance by the marks of the request, and has traveled that road — he has traveled it in the best manner. The Master then turned to the three counts of gratitude they had asked about, and answered each in turn. As for gratitude toward the Master, it is to obey him. As for gratitude toward the knowledge, it is to act upon what it contains and to call others to it. As for gratitude toward the work, it is to be patient in it and to call others to it.</p>
<p>As for the doctrines of the righteous and the manners of those who seek the truth: word has reached us that a man among the people of Persia was stricken with the affliction of ignorance. His heart was keen and retentive, his mind was sound, and he had cultivated learning within himself; yet ignorance ruled over him in the very knowledge already described, for it had seized him early and he had grown up surrounded by it. And so, in the heat of his thirst, he stumbled: he took the shimmer of the mirage for the whiteness of water, until he came to it and found nothing of it there. What he found instead was Allah, waiting for him, and there his account was settled. Then Allah honored his resting-place and lifted from him the veil that had covered him. He had found him astray and guided him; He had found him destitute and made him rich with knowledge. By that grace bestowed upon him, he became one of the scholars of the Mount (<span class="ar-inline" dir="rtl" lang="ar">اَلطُّور</span>) and one of those who dwell at the Frequented House (<span class="ar-inline" dir="rtl" lang="ar">اَلْبَيْتُ الْمَعْمُور</span>).</p>
<p>When his guidance was complete and he had reached the utmost of his hope, it became his duty to give thanks to his Maker and to labor his way toward his Lord. From his father he had heard a saying that was to him as the soul is to the body:</p>
<p class="ar-block"><span class="ar-inline" dir="rtl" lang="ar">إِنَّ أَفْضَلَ الْحَسَنَاتِ إِحْيَاءُ الْأَمْوَاتِ</span></p>
<p>&quot;The best of good deeds is the reviving of the dead.&quot; So he said to himself: &quot;I was dead, and He revived me; I was ignorant, and He taught me. I was not the first to be ignorant, that I should be the one who outstripped all people to knowledge, nor am I the last, that teaching should come to an end with me. It is a binding duty upon me to be one who gives thanks for this blessing, passing this trust on to those who come after me just as it was passed on to me by those who came before. For this matter has its origin with Allah, and it reached me only through a long chain of intervening causes — the first conveying it to the second, the second to the third, until it came down from the highest assembly to the creatures who are the people of this world. Then the veil was torn and the doors were forced open, one after another, until at last it reached me. Am I, then, its endpoint and its final limit? No. Those who carried it and kept faith with its trust have the prior claim to the gains and the merits. And if their gains are not mine to lean upon, then I am only the one who was gained for them through their labor. Their merit does not excuse me from labor of my own; I remain as poor in my need to seek knowledge through action as I once was poor in my need to seek knowledge at all.&quot; This he said within himself, and he understood that what he owed was the very likeness of what had been owed to him, and that the end of his affair, in the final reckoning, was like its beginning.</p>
<p>So he set out, leaving his family and his wealth behind, and turned toward his Lord — answering His call, praying for what is good, and summoning others to the obligation, so that the same thanksgiving which had become due from him might also become due to him. He took to traveling through the lands, passing among the peoples of the non-Arabs and the tribes of the Arabs, searching faces and putting questions, yet he found no one to answer him and met no fellow seeker, until he reached the farthest bounds of the island (al-Jazira (<span class="ar-inline" dir="rtl" lang="ar">اَلْجَزِيْرَة</span>)). He entered one of its cities at an hour when its people were heedless. And while he was calling the signs to mind and studying the marks, he caught sight of a company of the people of that land quarreling over religion without guidance and plunging headlong into the depths of their own caprice. So he sat down a little apart, withdrawn from them, listening to their words and watching them closely to see which among them held to the soundest way.</p>', 1160);
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('the-master-and-the-disciple', 'a stranger in the city', 3, '2. A Stranger in the City', '<p>He sat for a while, weighing them one against another, until he said within himself: of all those present, these men stand out in three qualities that make for a living debate. The first is that they carry an argument through to its end. The second is that they belong to the people of the Umma. And the third is that they are nearer to true awareness, for they keep to religion together and search it out together — and whoever seeks a thing is on the verge of finding it.</p>
<p>When they had finished the discussion they were engaged in, they turned to him and said, &quot;Who are you, boy, and where are you from?&quot;</p>
<p>He said, &quot;I am a servant of Allah, one of those who dwell in His sanctuary.&quot;</p>
<p>They said, &quot;What do you need, and what is your occupation?&quot;</p>
<p>He said, &quot;The thing I needed has slipped past me, and my occupation is the search for it.&quot;</p>
<p>They said, &quot;Did anything of what we said please you?&quot;</p>
<p>He said, &quot;All of it is a wonder to one who is inclined to wonder.&quot; They said, &quot;But wonder is of two kinds, the praiseworthy and the blameworthy.&quot;</p>
<p>He said, &quot;Yes, I have learned as much. And speech is the same: praiseworthy and blameworthy.&quot;</p>
<p>They said, &quot;Then which kind, in your view, is the praiseworthy?&quot;</p>
<p>He said, &quot;The kind that is correct.&quot; They said, &quot;And what is the correct?&quot;</p>
<p>He said, &quot;The speech whose origin is from Allah and which calls to Allah.&quot;</p>
<p>They said, &quot;And what is the blameworthy?&quot;</p>
<p>He said, &quot;The speech whose origin is caprice and which calls to something other than guidance.&quot;</p>
<p>They said, &quot;You have spoken truly. Have you no words of your own for us to hear?&quot;</p>
<p>He said, &quot;I have nothing to say. I am only a follower of the right word.&quot;</p>
<p>They said, &quot;Then let us hear from your words what may show us your way, for your condition has grown dear to us and your fellowship has become sweet to us, and we hope that you may be a door of mercy that Allah has opened to us.&quot;</p>
<p>He said, &quot;Yes.&quot; So he composed himself to speak, and the people fell silent to listen, and he turned his face toward them.</p>
<p>Then he said: &quot;He who created the creation by His power made each thing equal to the measure He decreed for it. He is the One who opened the highways of the pasture and kept their outward and their inward free of caprice, He who is not ambiguous and is not to be reached by the study of mere traces. Though imaginings are bewildered when they seek Him, and minds fall short of attaining Him, still He does not appear within created being so as to be possessed by His attributes, or so that the aim of His path might be altered. Rather He is generous. His knowledge is hidden by its very grace, and its secrets are guarded by those who are their rightful keepers. Its honor is the plumage of guidance, and it is completed by the garment of piety, marked with the light of lights, a deposit in the breasts of the righteous — the keepers of the Word, the honor of the scribes — a trust which they discharge and a bound which they do not exceed. It is the rule of the Judge and the bounty of the Most Merciful. He honored it and set it within, He protected it and concealed it, He granted it the sufficiency of its own rights and crowned it with His covenants. So the resolves of the thinkers do not reach it, and the schemes of the schemers do not arrive at it. Its outward is a remembrance and a proof for those who are guided, and its inward is a sure drink, whose sky is brought low for those who behold, whose land is paved for those who seek, and whose falling stars are stations for those who study. It has watering places for those who journey to Him, and signs whose wonders come one after another, pointing by their likenesses to Him. Its course is an advancement and its method a full unfolding. Its rulings are obligations and its practice is law. Truthfulness has ennobled its doctrines, and justice has refined its gains, so that He made it a leader and a way to every good, and made it a shield and a guide to its own inner chamber. Then, by ignorance and by want, He compelled minds to seek knowledge and capacity.</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">فَتَبَارَكَ الَّذِي جَعَلَ اللَّيْلَ وَالنَّهَارَ خِلْفَةً لِمَنْ أَرَادَ أَنْ يَذَّكَّرَ أَوْ أَرَادَ شُكُورًا، وَصَلَّى اللَّهُ عَلَى مَنِ اخْتَارَهُ مِنْ عِبَادِهِ وَجَعَلَهُ لِلْعَالَمِينَ نَذِيرًا</span>.</p></blockquote>
<p>&quot;Blessed is He who made the night and the day a succession for whoever would be reminded or would give thanks. And may Allah bless the one He chose from among His servants and made a warner to the worlds.&quot;</p>
<p>Then he said, &quot;Fear Allah with the fear of one who dreads Him, and fear Him with the fear of one who hopes in Him. Seek knowledge, and you will come to know. Act, and you will be shown mercy.&quot; Then his eyes overflowed with tears, and he broke off his speech and took his leave of the people weeping, and rose to return to his lodging, turning away. Weeping came over the company at the warmth of his words and the reach of his admonition, and they meant to rise and go with him. But good manners held them back from crowding after him all at once, for they did not know whether that would suit him, and so they returned to their dwellings. Yet one of the company followed after him: a youth, the youngest of them in years but the most forbearing in mind, his reason perfected by discipline and his heart kindled by thought, pressed now by all that he had heard.</p>
<blockquote class="aside editorial"><p><strong>Editorial note (tradition-grounded).</strong> <strong>A clarified term for this chapter.</strong> When the boy names being &quot;of the people of the Umma&quot; as one of the three qualities that make these men worth debating, the word carries more than &quot;community.&quot; Umma comes from a root meaning to aim toward and to head for a source — the same root that gives umm (mother) and imam, the one who stands at the front. An umma is thus a people bound together not by mere proximity but by facing one direction, gathered around a shared source and aim. This deepens the very reason he gives for choosing them: they are &quot;nearer to right awareness, for they observe religion together and search for it together.&quot; Their belonging to an umma is precisely their shared orientation toward one source — the disposition of a seeker who, as he says, &quot;is on the verge of finding it.&quot;</p></blockquote>', 1164);
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('the-master-and-the-disciple', 'the boy at the door — limits and conditions', 4, '3. The Boy at the Door — Limits and Conditions', '<p>The boy''s father was one of the most prominent Arab shaykhs—a man of noble lineage, yet also one of the fiercest enemies of religion. With the Master''s permission, the boy walked with him until they reached the place where the Master was staying. The Master invited him in and called for food. When they had eaten and settled into conversation, the boy spoke.</p>
<p>“Wise teacher,” he said, “your words have struck their mark. You have set religion before me with such beauty and conviction that you have stirred in me a longing to understand it. Wisdom like yours could come only from a man whose knowledge runs deep and whose patience is vast—a wellspring of wisdom rooted firmly in truth, whose branches bear fruit for everyone who seeks it. I believe you may be one of those blessed branches, for I see in you sound judgment, integrity, and a seasoned mind. You said that awareness of one''s own ignorance drives the mind to seek knowledge. No mind is more aware of its need than mine. Is there, then, a path by which I may reach true life?”</p>
<p>The Master replied: “The One who created all beings by His power did not create them without purpose. He did not bring them into being already possessing knowledge, nor did He abandon them to wander helplessly in ignorance. He did not mean foolishness to become their way of life, or ignorance their lasting state. Instead, He gave them the means to rise out of ignorance through the very faculties with which He completed their making. He granted them hearing, sight, and hearts able to receive light. These were at once a gift to them and a proof by which they would be held to account. God then placed the treasures of His wisdom and the signs of His will within the teachings He entrusted to His chosen servants. He charged them to guard religion and to call others to it, and He required humankind to answer through the faculties He had given them. In this way God sets the corrupt apart from the good. Those who seek sincerely are granted sight, while those who hang back through carelessness lay bare their own neglect. After the coming of God''s messengers, no one has an argument against Him; and after the evidence has been made plain, no one has an excuse for remaining astray.”</p>
<p>The boy said: “The thought that I may have no excuse frightens me, yet the presence of clear evidence fills me with hope. Show me the proof, and I will serve you in humility.”</p>
<p>The Master replied: “God did not create people as grown men or learned scholars. He created them as children who at first knew nothing. No one becomes great without first being small, and no one becomes learned without first passing through ignorance. Childhood is the beginning of maturity, just as ignorance can become the beginning of knowledge. In the same way, deeper knowledge cannot be received until simpler knowledge has come before it—knowledge that reaches the heart more quickly and is easier for the mind to grasp. Its foundations must first grow steady in the intellect. A person''s conduct must then bend to its demands, the heart must answer to its inner meaning, and only then can the mind carry its farthest conclusions.</p>
<p>“This is God''s settled way with His servants. We must not, then, invent religion according to our own opinions, or leave the recognized path under the pretense of seeking guidance.”</p>
<p>The boy said: “Then I am too young for what I long for—so help me grow. I am ignorant of what I seek—so teach me. I stand in need of your generosity—so have mercy on me. You were once in this very condition, and God brought His blessing to you through someone who bore great hardship for your sake and earned your lasting gratitude. I know what it is to suffer within the confinement of ignorance, to need a path and not know where to find it, and to have too few means to help oneself.”</p>
<p>The Master replied: “I was once in the condition you describe, and I am concerned for your welfare. But my compassion alone cannot bring you nearer your goal without effort on your part. Every claim must in the end be examined, and nothing should be accepted unless it is true. Knowledge is useless until it is put into practice, and action is useless unless it is worthy of acceptance. The soundness of speech lies in its truth and its fairness; the proof of knowledge shows itself in the lives and deeds of those who embody it. This testimony can be found across the world and across the generations. Do not accept or reject an argument carelessly. Do not accept a thing by mere imitation, without evidence, or the first doubt you meet may tear it from your heart. But once its proof stands firm, do not reject it, or you will become a defender of falsehood. And do not neglect careful inquiry, or your judgment will bear no fruit. Think well of me, but show me no blind favor. Question me in earnest, but without suspicion. Seek religion with the seriousness your condition deserves, and ask God to help you. When He sees that you truly seek what is good, He will neither waste your effort nor withhold its reward.”</p>
<p>The boy said: “You have dealt fairly with me and pointed me toward the truth with admirable clarity. I ask God for help, and now I ask you about the matter to which you call me. What is it? From whom does it come? And upon whom is it binding?”</p>
<p>The Master replied: “It is the religion of God—the religion He has accepted, and in place of which He accepts no other. It comes from Him. It was entrusted first to His chosen messengers and, through them, addressed to all creation. Whoever has been specially favored with it must give thanks, live by it, and call others toward it. Whoever has been deprived of it must seek it until he comes to know it, and then obey the one who guided him to it.”</p>
<p>The boy asked: “Is the blessing with which God has favored His friends the same in every case, so that they are equal in excellence? Or do some receive a greater share than others?”</p>
<p>The Master replied: “Have we not already said that every level of knowledge is preceded by a simpler one? Every blessing has people entrusted to carry it, and they stand in different ranks before their Lord. Each person is answerable according to the knowledge he has gained. God grants every person of excellence the rank that matches his excellence. This reflects both His justice toward creation and His mercy toward His servants.”</p>
<p>The boy asked: “Is the teaching to which you call me the fullness of that blessing, or is it something else?”</p>
<p>The Master replied: “It is neither the blessing in its complete reality nor something wholly apart from it. It is a part of that blessing—like a handful of water drawn from the vast Euphrates. I call you to what God has accepted for His servants and honored on the day He brought it to completion. It is precious and closely guarded, noble and hidden. God has tied reward to it, honoring those who preserve it, and punishment to its neglect, humbling those who squander it. Its outward form is symbols and practices, but its inward reality is knowledge. Its governing principle is light, and its justice is plain. This is what I call you toward.”</p>
<p>The boy said: “What gives you a greater right to this matter than anyone else? Why should you be more deserving of it, when you say it comes from God and is meant for creation as a whole? Everyone claims it for himself while denying it to others. Why should your claim to the truth be stronger than theirs, when this matter reached you through the same origins by which it reached them?”</p>
<p>The Master replied: “No scholar speaks a word of truth without having received it, in the end, from the same foundations from which we received it. In acknowledging those foundations, they agree with us, and we with them. What sets us apart from them is that they abandoned those foundations while we held fast to them. We obeyed where they disobeyed. We preserved what had been entrusted to us while they squandered it. We fulfilled the charge laid upon us while they fell short. So they agree with us in what they acknowledge, but differ from us in what they do. Their acknowledgment testifies for us and against them. Their neglect lays bare their poverty and their need for what remains in our hands. They are like brothers who inherited a great fortune from their father and divided it equally. Some squandered their share until they fell into poverty. Others guarded what they received and invested it wisely until it multiplied. In the end the impoverished brothers were driven to come to the prosperous ones, to serve them and seek their generosity. In the same way, those who squandered the teachings of their messengers are driven by ignorance to seek knowledge from those who preserved the original inheritance. The proof that we have the stronger claim to the truth is that they need what we possess, while we have no need of what they possess. Our learned instruct their ignorant; those among us who are clothed cover the nakedness of others; and those rich in knowledge feed those who hunger for it. The seeker of virtue must therefore submit to the truth. Honor belongs to the one who confers the benefit, and gratitude is owed to the one who bestows the gift.”</p>
<p>The boy said: “Your superiority over those who squandered their inheritance is now clear, and your argument stands established against the common people. But what argument do you have against me? I acknowledge what you affirm, reject what you reject, recognize the truth and its excellence, and know falsehood and those who follow it.”</p>
<p>The Master replied: “My argument against you is the same as my argument against them. You differ from them in what you profess, but in your actual condition you remain like them.”</p>
<p>“How can that be,” the boy asked, “when I acknowledge the rightful owner of the truth while they deny him?” The Master answered: “You differ from them by acknowledging what they deny, but you resemble them by withholding what they withhold. Acknowledgment without action is of no benefit. What finally matters is whether one turns toward the truth and acts upon it.”</p>
<p>The boy said: “Then once I know who the people of truth are, I will give them what is rightfully theirs—or I will turn to a representative authorized to receive it on their behalf. Show me which of these is possible.” The Master replied: “Do you not see that you now need to know who possesses the truth, or who lawfully represents him, just as the common people need proof of the truth itself? Your willingness to act sets you apart from them, but your want of knowledge still joins you to them.”</p>
<p>“You have spoken truly,” said the boy. “Then make the matter plain to me.”</p>
<p>The Master asked: “Have you not acknowledged that my argument is binding upon both you and the common people?”</p>
<p>“Yes,” the boy replied.</p>
<p>“Can anyone establish for himself a right that properly belongs to another?”</p>
<p>“No one can do that.”</p>
<p>“Then the argument stands established against both you and them. Nothing remains but to submit and turn toward the one whom you need, but who has no need of you.”</p>
<p>The boy said: “I acknowledge my need. I am seeking the One who has no need of me—so have mercy on me.”</p>
<p>The Master asked: “Have you ever known a man driven by poverty to seek the help of a generous man, and receive anything except through merit or through an act of grace?”</p>
<p>“No,” the boy answered. “He receives either what he has earned or what is freely given.”</p>
<p>“And does one who receives something purely as a gift share the merit of one who has earned it?” “No.” “Then pursue this matter through sincere effort, that you may attain it as something deserved. Do not pursue it through flattery, hoping to receive it merely as a favor, or you may find yourself deprived of it.”</p>
<p>The boy said: “You are the key to goodness and the guide toward it. Show me which path holds more meaning and which leads most directly to guidance. My great need has bound me firmly to you.”</p>
<p>The Master replied: “My son, what you seek is not beyond your reach, and you have done nothing to deserve reproach. What you hope to receive from me will come to you. But this path has limits that must not be crossed and conditions that must not be forgotten.”</p>
<p>The boy said: “Set whatever limits you wish and lay down whatever conditions you think proper. I hope you will find me patient under trial and grateful for your kindness.”</p>
<p>The Master said: “The first limit is that you uphold the outward teachings and laws of the Book, and act faithfully upon what you already know. For it is said:</p>
<p class="ar-block"><span class="ar-inline" dir="rtl" lang="ar">فَإِنَّهُ مَنْ عَمِلَ لِلَّهِ بِمَا يَعْلَمُ، هَدَاهُ اللَّهُ إِلَى مَا لَا يَعْلَمُ</span></p>
<p>Whoever acts for God according to what he knows, God will guide him to what he does not know.”</p>
<p>The boy replied: “But the revealed Books are many. All of them come from God, and each has scholars who hold fast to it. All of them claim to preserve their Book and the religion it contains.”</p>
<p>The Master said: “We have come back to the beginning of our discussion, and find ourselves having to establish what ought already to be clear.”</p>
<p>“How so?” asked the boy.</p>
<p>“You say the Books are many, that all come from God, and that each has its own scholars. Do you imagine that God''s words and His Books contradict or cancel one another—that the earlier Books call the later ones false, or that the later Books call the earlier ones false?”</p>
<p>“I do not believe that,” the boy said. “But what proves otherwise?”</p>
<p>The Master replied: “Had people faithfully followed the first Book, it would have guided them toward the second. Had they followed the second, it would have guided them toward the third. This succession would have gone on until they reached the final Book. That final Book is the one most fitting for them now, even though every revealed Book came from God. It is nearest to them in time and clearest about the teachings now required of them. It sets aside the rulings that came before it, while no later revelation has come to set it aside.”</p>
<p>The boy said: “You have spoken truly and marked out both the truth and the sign by which it may be known. I accept the limits you command me to observe. What conditions do you now place upon me?”</p>
<p>The Master replied: “My conditions are five: Do not fail me when I entrust you with something. Do not conceal anything from me when I question you. Do not come looking for me; wait until I answer you. Do not ask me for anything until I first raise the matter with you. And do not speak of my affair to your father.”</p>
<p>The boy said: “I will keep all these conditions. They are easy beside the greatness of what I hope to receive from you. But what am I to do about my father? He is one of my heaviest trials and a source of deep distress to me. Will you permit me to leave him?”</p>
<p>The Master replied: “If you leave him, you will draw attention to yourself. Stay with him instead. Treat him dutifully and outwardly accommodate him where you can. Keep your secret from him and hide what you are doing. God will protect us from any harm he or anyone else might do.”</p>
<p>The narrator continued: The Master and the boy met from time to time, but long stretches often passed between their meetings. The boy remained unsure of his situation. He knew only the limits laid upon him. He did not know where the Master lived, and because of the Master''s condition, he was forbidden to go looking for him. Time passed in this way. The Master was testing the boy''s patience while showing his own patience in carrying out the charge entrusted to him. At last, on a quiet night, when the world had fallen silent, and the informers had grown careless, the two were brought together again. The boy felt the full weight of his need and was finally granted privacy with his teacher.</p>
<p>He fell prostrate before the Master. When he raised his head, the Master said: “I saw you prostrating in gratitude. Gratitude offered before a deed is complete may arouse suspicion, while gratitude that ends too soon after its completion may render one''s efforts meaningless.”</p>
<p>The boy replied: “Everything you say is true, and everything you do is wise. I gave thanks for the kindness you have already shown me, and through this prostration of gratitude I hoped you might grant me still more.”</p>
<p>The Master said: “Gratitude truly deserves an increase, and you have now established your right. Turn your heart toward me, fix your mind, and listen closely to what I am about to set before you.” The boy replied: “I have made ready my understanding and prepared myself to listen. Say whatever you think best.”</p>
<p>The Master said: “Religion has a key by which the lawful is set apart from the unlawful, just as lawful marriage is set apart from fornication.”</p>
<p>The boy replied: “This key must be of tremendous weight in the sight of God, since it parts the lawful from the unlawful and truth from falsehood. What is it?”</p>
<p>The Master said: “It is the covenant of God. Through it, His rights are affirmed, and His obligations gathered together. It is a shield for His friends, God''s rope stretched across the earth, and His secure pledge among His servants. I will recite this covenant to you and receive your commitment to it.”</p>
<p>The boy replied: “Yes. Take from me whatever commitment you require. I will neither reject your judgment nor turn from your path.”</p>
<p>The narrator continued: The Master then recited the covenant to the boy slowly, explaining it with care and binding him firmly to its obligations. The boy was overcome with awe and could not hold himself back. Tears streamed down his face until the Master reached the end of the covenant. The boy praised and glorified God and thanked Him for the blessing he had received. He grew certain that, by accepting the covenant, he had entered the Party of God—the company of His devoted friends. He then fell silent and regained his composure. The Master began the detailed exposition and explanation.</p>
<blockquote class="aside editorial"><p><strong>Editorial note (tradition-grounded).</strong> A related teaching preserved in this tradition illuminates the Master''s principle here that &quot;knowledge cannot be borne unless a lesser knowledge is brought in before it&quot;: the human being, unlike the animal that has sound but no rational speech, learns gradually from his parents through metaphorical speech until he reaches adulthood. That is the same graded ascent the Master describes to the boy — smallness as the prelude to greatness, a simpler knowing &quot;quicker to reach the hearts and smoother to the understanding&quot; laid down first so the mind can steady itself before bearing the harder end of knowledge. The faculty of rational utterance the boy praises in the Master, and now seeks for himself, is precisely the instrument by which this gradual instruction becomes possible at all.</p></blockquote>', 3335);
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('the-master-and-the-disciple', 'how the world was made', 5, '4. How the World Was Made', '<blockquote class="aside bridge"><p><strong>A note for the reader.</strong> <em>Everything that follows to the end of this chapter is the Master''s own discourse to the boy, so the &quot;I&quot; and &quot;we&quot; in it are his and not the edition''s.</em></p></blockquote>
<p>God is the Creator of all things and the One who composes them: He made them and brought them into being. He is not merely the first of each created thing, cited as evidence for what came after Him; He is the First of all firsts and the Inheritor of every existing thing. He began the creation of all He made out of a light, and from that light three words branched. The first is the will; from the will branched the command; and from the command branched the saying — that He says &quot;Be&quot; to whatever He wills, and it is. So the first of creation was a will, then a command, then a saying.</p>
<p class="ar-block"><span class="ar-inline" dir="rtl" lang="ar">فَابْتَدَأَ خَلْقَ مَا خَلَقَ مِنْ نُورٍ تَفَرَّعَ مِنْهُ ثَلَاثُ كَلِمَاتٍ</span>. <span class="ar-inline" dir="rtl" lang="ar">أَوَّلُهَا إِرَادَةٌ، وَتَفَرَّعَ مِنَ الْإِرَادَةِ الْأَمْرُ، وَتَفَرَّعَ مِنَ الْأَمْرِ الْقَوْلُ لِمَا يَشَاءُ كُنْ فَيَكُونُ</span>. <span class="ar-inline" dir="rtl" lang="ar">فَكَانَ أَوَّلُ الْخَلْقِ إِرَادَةَ أَمْرٍ بِقَوْلٍ</span>.</p>
<p>He began the creation of what He created out of a light from which three words branched. The first of them is the will; from the will branched the command; and from the command branched the saying, that He says &quot;Be&quot; to what He wills, and it is. So the first of creation was a will, a command, by a saying.</p>
<p>These are three words, and from them is derived <span class="ar-inline" dir="rtl" lang="ar">كُن</span> (Kun), which is two letters, and <span class="ar-inline" dir="rtl" lang="ar">فَيَكُون</span> (fa-yakun), which is five — seven letters in all; and from these seven letters seven things branch. Out of the light He created the air, the first of them: single and without consort, unique among all things, mingling with them and enclosing them, yet enclosed by none. It is the proof of the One of whom &quot;there is nothing like Him.&quot; Then, out of these three words, He created water, darkness, and light — the light of the heavens and the earth. From the water He created smoke; from the darkness He created the condensation of heat; and from the light He created fire. These are three things branching from the three before them, and each became a consort to its origin, since it was created from it. The seventh, the air, holds sway over them all. Such was the beginning of creation and the beginning of things.</p>
<p>Once creation had been established upon seven principles, and the succession of forms had been laid down according to likeness and analogy, He created the seven heavens and their signs out of the smoke, and the seven earths and their sustenances out of the condensation of heat. These are the seven branches drawn from those seven origins.</p>
<p>The Master then turned to the signs of the heavens and the sustenances of the earth — what they are, and what bears witness to them — returning in his account to the three words and their letters, from which the seven were created: namely, &quot;the will to command by a saying.&quot;</p>
<p class="ar-block"><span class="ar-inline" dir="rtl" lang="ar">فَرَجَعْنَا فِي الْقَوْلِ إِلَى الْكَلِمَاتِ الثَّلَاثِ وَحُرُوفِهِنَّ الَّتِي مِنْهَا خُلِقَ السَّبْعَةُ، وَهِيَ إِرَادَةُ أَمْرٍ بِقَوْلٍ</span>.</p>
<p>So we returned in the saying to the three words and their letters from which the seven were created, which are: a will, a command, by a saying. That comes to twelve letters. Their signs in the heaven are the twelve constellations, whose witnesses are seven kingdoms; their signs upon the earth are twelve islands, whose witnesses are seventeen seas. These are the signs of the heavens and the earth, which people pass by while turning away from them.</p>
<p>Then the heavens and the earth were sealed together in darkness, out of the black heat that belongs to the dominion of the earth. He then rent them apart with His lights, and the light and the darkness — the two contrary realities — were mingled. He set a division between them by the night and the day, as two signs. He made the night, whose sign is a course of darkness, and He apportioned it; and He made the day, whose sign is a course of light, and He apportioned it. The night is dim with its darkness, and the moon and the stars are its sign; the day is radiant with its light, and the seeing of the sun is its sign. From the two of them the days were brought forth, alternating between night and day — and they are seven days. Their sign is that each of these days has twelve hours, and each of these nights twelve hours.</p>
<p>When the creation of things had been completed upon these principles, He made them in pairs, male and female — not male and female in the bodily sense, but in the sense of the superior and the subordinate. Then the practice went forth of creating in pairs, and out of their substances He created every living thing: humankind, beasts, birds, and crawling creatures. This practice then extended into speech, so that speech too became paired: attributes and things described, names and meanings. Glory be to Him who created all the pairs and made them the outward showings of His command, the likenesses of His religion, and the proofs of His power — pointing, through things, to their Originator, and through the creation, to its Maker.</p>
<p>Then He rent it apart with His light, opened it with His command, created it by His knowledge, and sealed it, out of His names, with the letters of &quot;In the name of Allah, the Most Gracious, the Most Merciful.&quot; <span class="ar-inline" dir="rtl" lang="ar">بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ</span> In the name of Allah, the Most Gracious, the Most Merciful. When He had perfected them all by His making and joined them into pairs by His measure, He chose for Himself — out of the purest of His will and the depths of His unseen — an abundant knowledge and a manifest light, and made the two of them a religion by which God is served and through which nearness to Him is sought. He then honored it with the sacred laws and the books, and made it known through likenesses and customs. Out of the choicest of His creation He raised up for it banners, proofs, and rulers, making them the houses of His prophethood, the treasuries of His knowledge and wisdom, and the interpreters of His revelation. He set them as His successors in His earth, guides to the path of deliverance in both the outward and the inward. Among them are the imams and the speakers (<span class="ar-inline" dir="rtl" lang="ar">النُّطَقَاءُ</span>); among them are the proofs (<span class="ar-inline" dir="rtl" lang="ar">اَلْحُجَج</span>) and the chiefs (<span class="ar-inline" dir="rtl" lang="ar">اَلنُّقَبَاء</span>); and among them are the summoners to the good and the learned. In their stations they are like the stars of heaven, by whom works are set aright and in whom the likenesses reach their end. Their imam is like the great sun among the lights, veiled by its own coverings from the sight of eyes, and he is its outward showing and its likeness. The proof and gate of their imam is like the shining moon, and he too is its outward showing and its likeness. Their summoners are like the radiant stars (<span class="ar-inline" dir="rtl" lang="ar">اَلزَّوَاهِر</span>), and they are its outward showings and its likenesses.</p>
<p>All the pairs the Master had described are outward and inward, likeness and thing likened. The outward of the seven heavens are likenesses, and their inward are the seven speakers, the messengers of firm resolve. The seven earths are outwardly likenesses, and their inward are the imams of guidance. To each speaker among them belong twelve chiefs, whose likeness from the seven heavens are the twelve constellations. Likewise, to each imam among the imams of guidance belong twelve proofs, by whom God''s argument is established upon his people, and whose likeness in the earth are the twelve islands.</p>
<p class="ar-block"><span class="ar-inline" dir="rtl" lang="ar">حُجَّةٌ يَحْتَجُّ بِهَا عَلَى قَوْمِهِ، وَمِثْلُهَا مِنَ الْأَرْضِ اثْنَتَا عَشْرَةَ جَزِيرَةً</span>.</p>
<p>Proofs by which the argument is established upon his people, and their likeness in the earth are twelve islands. The islands are the dwellings of the chiefs, and on every island there stands a proof. To every proof belong summoners, many and few. God increases in creation whatever He wills, so that the argument may reach its end — the argument of God upon His creation — that people may have no argument against God after the messengers.</p>
<p>Through these causes — the causes of God the Master had described — the argument of God reaches His creation, and His justice appears among them, outwardly and inwardly. The inward is the religion of God, by which the friends of God have been bound; the outward is the sacred laws of the religion and their likenesses. So the religion became to the laws a soul and a spirit, and the laws became to the religion a body and a proof. The body cannot stand except by the soul, for the soul is its life; and the soul cannot stand except by the body, for the body is its vessel. In the same way, the outward things — the sacred laws and the rest — cannot stand except by the inward religion, because it is their light and their meaning, the spirit of life within them; and the inward cannot stand except by the outward, because the outward is its body and its proof. The outward is the knowledge of this world, and nothing is seen except by it; the inward is the knowledge of the hereafter, and nothing is seen except by it. There is not a single letter among the letters of the inward, nor a single friend among the friends of God, but that its witnesses in the outward are many, because of the abundance of the likenesses and the breadth of the sacred laws.</p>
<p>The discourse upon this is long, and it grows ever greater; and the more its answer multiplies from the words of wisdom, the more its rightness is veiled, and its end makes one forget its beginning, because of its preciousness and the purity of its essence. For the light of wisdom overcasts one part of itself with another, just as the light of the sun overcasts the light of the moon and the stars and dims them. So too do the words of wisdom adorn the tongue of the man who is wise.</p>
<p>Editorial note (tradition-grounded). Where this chapter closes by naming &quot;the signs of the heavens and the earth, which people pass by while turning away from them,&quot; it is echoing a specific verse the reader may not recognize: And how many a sign in the heavens and the earth they pass by, while they are averse therefrom (Yusuf: 105). The chapter''s whole architecture — the twelve constellations and twelve islands, their heavenly and earthly witnesses — is offered as a catalog of exactly these overlooked signs. It is worth pairing this with the chapter''s earlier note on the air as &quot;the proof of the One of whom there is nothing like Him&quot;: for the Master, the sign that points to God is precisely the one unlike every other sign.</p>', 1876);
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('the-master-and-the-disciple', 'the world, the hereafter, and the speech of parables', 6, '5. The World, the Hereafter, and the Speech of Parables', '<p>The boy then turned to a question that had long weighed on him, and said: This world, in which so vast a creation was set, holds a great multitude of people, the first of them and the last, and they differ about it. Some have given themselves over to it and chased after it, seeing no worth in anything but gathering more of it. Others reproach it and hold themselves back from it, yet do not do without it altogether — even though everything whose abundance is forbidden has its small measure forbidden too. From you I have heard neither mention of it nor any account of it. What do you say of it?</p>
<p>The Master said: As for this world, no one has ever truly reproached it, neither the learned nor the ignorant. The ignorant man knows its worth through his very ignorance of what lies beyond it, and the learned man knows its worth through the worth of its meaning. None reproaches this world but an ignorant man. How could the creation be permitted to reproach the act of the Creator? But here is my word concerning it: for one who has eyes to see, the world is built upon seven things that branch from seven origins — heaven, earth, darkness, light, vessels, blessing, and hardship. These are seven qualities, and from each of the seven there branch seven more: (a) The heavens are seven. (b) The earths are seven. (c) The light has seven days that turn upon seven nights. Saturday is for repose and rest; Sunday is for the bounds and the year; Monday is for the doublings, in the great meaning; Tuesday has three houses — an apparent, an inward, and an inward of the inward; Wednesday is for the four sacred things; Thursday is for the fifth of the causes of God; and Friday is the greatest law of God. (d) The darkness is seven nights, a shelter set over the seven days, for each day its night. (e) The vessels are seven: camels, horses, mules, donkeys, elephants, oxen, and ships. By these seven the empty tracts of the earth are crossed. Camels are for the sands, horses for the plains, mules for the mountains, donkeys for near destinations, elephants for the wastes and the desolate places, oxen for the salt-flats and the thickets, and ships for the seas. Seven mounts for seven domains. (f) The blessings of this world rest upon seven: air, water, light, darkness, food, clothing, and marriage. The air is the open space between heaven and earth, in which the winds arise and the breaths pass back and forth, and it is the life of every living thing. Water is the life of the animal. Light is the substance of sight; darkness is the increase of what grows; food is the sustenance of bodies; clothing is a covering that hides what should be hidden; and marriage is the seed of reproduction and the cause of offspring. Some of these are keys to the good, and some are mines of blessings. Which of them is blameworthy, when all of them come from the hands of God and are among His blessings, for which His servants are bound to give thanks? (g) Their opposites in hardship are seven as well: heat, cold, hunger, thirst, fear, sickness, and death. These are seven that must be borne with patience, once their meaning is known.</p>
<p>The boy said: These are the attributes of the world, and I do not doubt that anything in it is other than the making and the composing of the Creator. So what do the learned mean when they censure the world, and what do the ignorant mean when they praise it? I see that the ignorant have struck upon the meaning, even in their ignorance; and if that is so, then the rightness of their case would put the learned in the wrong, since the learned contradict the people of ignorance in every sense.</p>
<p>The Master said: The learned did not err in censuring this world, but the creation does not know what they mean by it. And the ignorant grasped no rightness in what they praised of the world, for they were ignorant of its meaning; and whoever is ignorant of a thing treats it as an enemy.</p>
<p>The boy said: Then make plain to me the truth of what the learned say, so that their truthfulness may be established for me. And set apart the speech of the people of ignorance by what shows its falsehood, since the outward appearance points the other way. My chest has grown narrow from ignorance of this, and I hope for no relief except through its knowledge.</p>
<p>The Master said: This world, and all that I have described to you of it, is an outward for an inward. It has no subsistence except by that inward, for the inward stands to it as the soul stands to the body. Whoever knows the soul, the body is made wholesome for him; and whoever does not know the soul and acknowledges only the body — to him the body is a carcass, and the carcass is forbidden. From here the learned forbade the world, because it is dead. They forbade the dead thing that God has forbidden,</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">مِنْ حَيْثُ يَشَاءُ اللَّهُ</span>. <span class="ar-inline" dir="rtl" lang="ar">وَبَانَ كَذِبُ أَهْلِ الْجَهْلِ بِمَدْحِ الدُّنْيَا إِذْ لَمْ يَعْرِفُوا بَاطِنَهَا وَمَا أَرَادَ اللَّهُ بِهَا</span>. <span class="ar-inline" dir="rtl" lang="ar">وَظَنُّوا أَنَّ اللَّهَ خَلَقَهَا لِغَيْرِ مَعْنَاهَا، وَاللَّهُ لَمْ يَخْلُقِ الْأَشْيَاءَ عَبَثًا</span>. <span class="ar-inline" dir="rtl" lang="ar">وَلَوْ كَانَتِ الدُّنْيَا وَمَا فِيهَا لَمْ يُخْلَقْ إِلَّا لِلدُّنْيَا، يُنْشِئُ فِيهَا خَلْقًا</span></p></blockquote>
<p>until it is taken up in the way God wills. And the falsehood of the people of ignorance became plain in their praise of the world, for they did not know its inner meaning nor what God intended by it. They supposed that God created it for some meaning other than its own, yet God did not create things in vain. Had the world and all that is in it been created only for the world — so that He raised up in it a creation that then fades away — it would carry no consequence and no meaning. Every act without consequence is play, and every speech without meaning is falsehood, and God is far exalted above that.</p>
<p>The boy said: The truthfulness of the learned is now established, and their excellence is proven, and the people of ignorance are set apart and their falsehood is plain in what has appeared of the argument. There remains for us the knowledge of the inward of the world and what is in it. I see that the narrowness I complained of to you has had its narrowness lifted.</p>
<p>The Master said: What is the reward of one who brings you out of the narrowness of want into the breadth of ease?</p>
<p>He said: Thanks and praise.</p>
<p>The Master said: And what is the reward of one who brings you out of the narrowness of ignorance into the breadth of knowledge?</p>
<p>He said: Obedience and works.</p>
<p>The Master said: This world and all its likes are an outward for the hereafter and what is in it; the hereafter is its soul and its life. Whoever labors in the world for the world, with no knowledge of the hereafter, his labor is misguidance, for it has no meaning and no consequence. But whoever labors in the world for the hereafter, believing in it, his labor has meaning and consequence, and his labor is thanked.</p>
<p>The boy said: You have spoken truly. Now make plain to me the features of the world and what is in it, and set the parables against the things they portray from their inward side.</p>
<p>The Master said: God, blessed and exalted, has not created a single one of the things of the world — no beast upon the earth, no bird that flies with its wings, nothing moist and nothing dry, nothing fixed and lifeless such as the mountains, the stones, the trees, the minerals of gold and silver and gem —</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">، وَجَمِيعُ الْأَشْيَاءِ مَا كَبُرَ مِنْهَا وَمَا صَغُرَ، إِلَّا وَهُوَ مَثَلٌ مَضْرُوبٌ</span>. <span class="ar-inline" dir="rtl" lang="ar">أَلَا تَرَى الذَّرَّةَ عَلَىٰ صِغَرِهَا وَلُطْفِ مَعْنَاهَا لَهَا حُدُودٌ، أَمَامَهَا وَخَلْفَهَا وَيَمِينَهَا وَشِمَالَهَا وَفَوْقَهَا وَتَحْتَهَا؟ فَذَٰلِكَ سِتَّةُ حُدُودٍ وَهِيَ الْحَدُّ السَّابِعُ</span>. <span class="ar-inline" dir="rtl" lang="ar">فَكَذَلِكَ جَمِيعُ مَا خَلَقَ اللَّهُ مِنَ الْأَشْيَاءِ</span></p></blockquote>
<p>nothing at all, great or small, except that it is a parable struck. Do you not see the atom, for all its smallness and the subtlety of its meaning, that it has limits — before it and behind it, to its right and to its left, above it and below it? Those are six limits, and the seventh is the atom itself. So it is with everything God has created, from the ant and the gnat up to what is above them of the heaven and the earth, and what lies between them of things great and small. This is the parable: each of them has six limits, and the seventh of them is the proof of it, pointing to the six origins from which things were created. And the air that surrounds them is the seventh, encompassing them all and holding them. If your chest is wide enough for such questions, and for looking into the parables, and for setting each thing against its form among the hidden pairs, then ask about what has occurred to you.</p>
<p>The boy said: What is the likeness of the heaven, in its height above things and the breadth of its regions, such that it has gathered in all things?</p>
<p>The Master said: Its likeness is the likeness of the Speaking Imam (<span class="ar-inline" dir="rtl" lang="ar">الْإِمَامُ النَّاطِق</span>), who is raised above all creation by his excellence and the loftiness of his ranks, and who has gathered in all the rulings — the rulings of the Sharia — by the breadth of his knowledge.</p>
<p>The boy said: What is the likeness of the zodiac and the rest of its stars?</p>
<p>The Master said: They are the likeness of the twelve chiefs (<span class="ar-inline" dir="rtl" lang="ar">اَلنُّقَبَاء</span>), the chiefs of the Speaking Imam; and their stars are his summoners (<span class="ar-inline" dir="rtl" lang="ar">الدُّعَاة</span>), who call to the good by the leave of their Lord.</p>
<p>The boy said: What is the likeness of the earth and its breadth, since it was made a resting-place and a bed for this creation?</p>
<p>The Master said: It is the likeness of the gate (<span class="ar-inline" dir="rtl" lang="ar">بَاب</span>) of the Speaking Imam in his lifetime, and of his executor (<span class="ar-inline" dir="rtl" lang="ar">اَلْوَصِي</span>) after his death. He is a place of return for the people and a resting-place for whoever seeks guidance, being a knower of the parables and of the inner interpretation (<span class="ar-inline" dir="rtl" lang="ar">اَلتَّأْوِيل</span>).</p>
<p>The boy said: What is the likeness of the twelve islands in the earth? The Master said: The likenesses of the twelve proofs (<span class="ar-inline" dir="rtl" lang="ar">اَلْحُجَج</span>), the proofs of the executors.</p>
<p>The boy said: What is the likeness of its rivers and its springs?</p>
<p>The Master said: The likenesses of the summoners to the good (<span class="ar-inline" dir="rtl" lang="ar">الدُّعَاة</span>).</p>
<p>The boy said: What is the likeness of the seven kingdoms of the heavens and their orbits?</p>
<p>The Master said: Those are causes between God and the Speakers (<span class="ar-inline" dir="rtl" lang="ar">اَلنَّاطِق</span>), and they belong to Him. These are the seven and the two orbits, and these are the greatest causes of God.</p>
<p>The boy said: What is the likeness of the seven seas?</p>
<p>The Master said: These are causes between God and the imams of the Speaker, below those first causes.</p>
<p>The boy said: What is the likeness of the salt water and the fresh water, and the difference between them, upon the earth?</p>
<p>The Master said: The salt water is the likeness of the knowledge of the outward, in which there is no summons (<span class="ar-inline" dir="rtl" lang="ar">دَعْوَة</span>) and no summoners, just as the salt water yields no sowing and nothing else. The fresh water is the likeness of the knowledge of the inward — whether the springs within the earth or the water that runs upon its surface. So too is knowledge: the knowledge of the inward is of two kinds, an outward that the summoners carry along, and an inward that is kept concealed.</p>
<p>The boy said: How did water come to be a likeness of knowledge?</p>
<p>The Master said: Because water is the life of every living thing, and likewise knowledge is the life of every knower.</p>
<p>The boy said: What is the likeness of the air that surrounds all things?</p>
<p>The Master said: The air is too great to be made a likeness of any thing portrayed.</p>
<p>The boy said: Is it greater, or are the heaven and the earth as great as it, that they should be its likenesses?</p>
<p>The Master said: Glory be to God, it is greater than both of them. The breadth of the earth within the atmosphere is as a ring set down in an open plain; the breadth of the atmosphere within the sky is as a ring set down in an open plain; and the breadth of the sky and its regions within the breadth of the air is as an egg set down in an open plain. What thing portrayed could grasp this, so as to be a proof of it and a likeness for it?</p>
<p>The boy said: What, then, is its meaning?</p>
<p>The Master said: It is a proof of the One to whom nothing is like, glorified and exalted above what they associate with Him.</p>
<p>The boy said: But did the Creator not say,</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">فلا تضربُوا للهِ الأمثالَ</span></p></blockquote>
<p>&quot;Do not strike parables for God&quot;?</p>
<p>The Master said: And did He not also say,</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">وَللهِ المَثْلُ الأعْلَى</span></p></blockquote>
<p>&quot;And to God belongs the highest likeness&quot;?</p>
<p>The boy said: Glory be to Him who set riddles in His Book so that it might be entered by its door, and you are one of its doors. Make plain to us, then, how this is.</p>
<p>The Master said: Everything has a meaning, and the meaning of the parables is this: the outward is an indication of the inward. He, blessed and exalted, forbade that He be measured against anything of His creation, so that one should say,</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">هَٰذَا مَثَلُ الْإِمَامِ</span></p></blockquote>
<p>&quot;This is like the Imam,&quot; or</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">هَٰذَا مَثَلُ الْحُجَّةِ</span></p></blockquote>
<p>&quot;This is like the proof,&quot; or</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">هَٰذَا مَثَلُ الدَّاعِي</span></p></blockquote>
<p>&quot;This is like the summoner.&quot; For their likenesses became indications pointing to them and to the differences of rank among them. It is not permitted, in the matter of His greatness, that the Creator be measured against anything of His creation by word or by deed, so that one should say, &quot;This is like God.&quot; Rather the parables are taken according to their meanings, for their meanings carry indications: the small of them points to the great, and the great points to the higher meanings, and the higher points to the Highest of the high. Therefore He said,</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">وَللهِ المَثَلُ الأعْلَى</span></p></blockquote>
<p>&quot;And to God belongs the highest likeness&quot; — meaning the highest indication, for there is no indication of anything higher than the indication of God. And that is the air, highest above the heaven and the earth, encompassing all things while nothing of them encompasses it. It is the highest likeness, and it is the indication of the One to whom nothing is like. He did not say that there is nothing like Him — for indeed there is nothing like Him — but He meant that no indication of Him is like the indications, that to Him belongs the highest likeness, and that no indication among the indications of others, from those of His creation whom we have described, is like the indication of Him. Blessed be God, Lord of the Mighty Throne.</p>
<p>The boy said: The meaning has grown great and the reach has grown wide. Was there, before the air, a thing standing between it and God, given the greatness of what you have described in it?</p>
<p>The Master said: Yes.</p>
<p>The boy said: What is it?</p>
<p>The Master said: It is the time. The boy said: And what is time?</p>
<p>The Master said: It is the time of the Will by which He created what He willed and commanded what He wished.</p>
<p>The boy said: You have brought me into the deeps of the seas, down from the highest assembly. Return me now to the sciences of the world and its parables, that I may seek help by them in my affair and be strengthened by them to bear what I am meant to bear. I have grown afraid for myself and anxious for my mind, lest I be led into what I have not the strength to fathom.</p>
<p>The Master said: You rose high by your question, and the answer rose high with you, to the highest of the outward meanings — and there your thought lost its way and your mind was confounded. How would it be, then, if I disclosed its inward to you? You and I would be as Moses and the knowing one.</p>
<p>The boy said: And does this inward have an inward, more inward than itself?</p>
<p>The Master said: By my life, the inward has an inward that is higher in station, wider in power, and more perfect in guidance; it is the utmost of the indications toward the path of deliverance.</p>
<p>The boy said: I see here three layers of knowledge: an outward, an inward, and an inward of the inward. Is there a proof of this? The Master said: And where would the proof be, if not for this and for what it points to?</p>
<p>The boy said: Then show me a likeness of these three layers.</p>
<p>The Master said: I will show you from the Book of God Almighty, and from the proof of the intellect, and from what the general body of the parables points to.</p>
<p>The boy said: I did not think there was, beyond what I had reached, any doctrine at all. Truly the command of God is greater than the imaginings of the pretentious can rise to.</p>
<p>The Master said: As for the Book of God Almighty, it is His saying,</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">يَا بَنِي آدَمَ قَدْ أَنْزَلْنَا عَلَيْكُمْ لِبَاساً يُوَارِي سَوْآتِكُمْ وَرِيشًا وَلِبَاسُ التَّقْوَى ذَلِكَ خَيرٌ</span></p></blockquote>
<p>&quot;O children of Adam, We have sent down upon you a garment that hides your nakedness, and feathers for adornment; and the garment of piety — that is better.&quot; These are three: an outward, an inward, and the inward of the inward.</p>
<p>The boy said: You have spoken truly.</p>
<p>The Master said: As for the proof of the intellect, a thing is not known except by a name, or an attribute, or a meaning. The meaning is the very essence of the thing; the name is what it is called; and the attribute is an indication of it. So too is the religion of God: it has an outward, which is a name, and an inward, which is an indication of it, and it stands only by the two together. Nothing indicates a thing except a name or an attribute. Consider the saying of one who says &quot;<span class="ar-inline" dir="rtl" lang="ar">طَلَعَ الْقَمَرُ</span>,&quot; &quot;the moon has risen.&quot; The meaning is the disk; &quot;<span class="ar-inline" dir="rtl" lang="ar">اَلْقَمَر</span>,&quot; &quot;the moon,&quot; is its name; and &quot;<span class="ar-inline" dir="rtl" lang="ar">طَلَع</span>,&quot; &quot;has risen,&quot; is its attribute. Were he to say &quot;<span class="ar-inline" dir="rtl" lang="ar">قُرْص</span>,&quot; &quot;a disk,&quot; and then fall silent, it would carry no meaning. And were he to say &quot;<span class="ar-inline" dir="rtl" lang="ar">قَمَر</span>,&quot; &quot;a moon,&quot; and then fall silent, it would carry no meaning — until he joins the name to the attribute and says &quot;<span class="ar-inline" dir="rtl" lang="ar">طَلَعَ الْقَمَرُ</span>,&quot; &quot;the moon has risen,&quot; and then the meaning is made clear and the speech is sound. In the same way, if you say &quot;<span class="ar-inline" dir="rtl" lang="ar">ظَاهِر</span>,&quot; &quot;an outward,&quot; it calls for an answer, that one should ask, &quot;an outward of what?&quot; And if you say &quot;<span class="ar-inline" dir="rtl" lang="ar">بَاطِن</span>,&quot; &quot;an inward,&quot; it calls for an answer, that one should ask, &quot;an inward of what?&quot; But if you say &quot;<span class="ar-inline" dir="rtl" lang="ar">ظَاهِرُ الدِّينِ وَبَاطِنُهُ</span>,&quot; &quot;the outward of the religion and its inward,&quot; the speech is understood, and it becomes a religion having an outward and an inward, just as a thing has a name and an attribute. So He said,</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">وَذَرُوْا ظَاهِرَ الإِثْمِ وَبَاطِنْهُ</span></p></blockquote>
<p>&quot;And forsake the outward of sin and its inward.&quot; So sin became a thing having an outward and an inward. Such too is the greater religion of God, of which it is said that the laws are its outward and the inward is its inward, and it subsists by itself. And for the knowing of its meaning there are many parables that point to it, such as the guarded egg, which has an outward that shelters it, an inward which is the white within it, and an inward of its inward which is the yellow yolk — and that is its essence and its meaning.</p>
<blockquote class="aside editorial"><p><strong>Editorial note (tradition-grounded).</strong> This chapter turns on a single figure: the world is an outward whose life depends on an inward, &quot;as the soul stands to the body.&quot; A related teaching preserved in this tradition names the soul so invoked plainly — the Commander of the Faithful calls the universal soul &quot;a divine force,&quot; vast in essence, &quot;the origin from which one seeks help and to whom one calls.&quot; Read against that, the Master''s warning is precise: a body known only as body, cut off from that animating origin, is a carcass. The chapter''s other pillar — that God &quot;did not create things in vain,&quot; that an act without consequence is mere play — rests on the same conviction voiced when this cosmology describes creation itself: the spiritual world was brought forth deliberately, from nothing, for a meaning of its own. The world is forbidden by the learned not because it is worthless, but because, taken as dead, it hides the inward that alone makes it real.</p></blockquote>', 3639);
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('the-master-and-the-disciple', 'three layers of knowledge', 7, '6. Three Layers of Knowledge', '<p>The boy said: &quot;Are not this world and the hereafter a pair, the soul and the body a pair, the knowledge of the outward and the knowledge of the inward a pair — and are there not many such pairs besides these?&quot;</p>
<p>The Master said: &quot;I grant it. But are they pairs of a single kind?&quot;</p>
<p>The boy said: &quot;The pairs point toward the religion of God.&quot;</p>
<p>The Master said: &quot;I grant that too. Within each pair, the outward is a name and the inward is an attribute, and the attribute signifies the knowledge of God and the religion of God, which is the inner meaning. In the same way, creation was set upon three stations: first the creation of the angels, second the creation of human beings, and third the creation of the beasts. The outward is the knowledge that marks the limit of the beasts; whoever knows it alone, without the inward, stands at the level of the beasts. The knowledge of the inward is the knowledge of the children of Adam and marks their limit; whoever knows it is a believer, at the level of a true human being. The knowledge of the inner of the inward is the knowledge of the angels; whoever knows it becomes spiritual in his knowledge though bodily in his frame, and he is a prophet sent by God in His land, through whom God establishes His argument against His creation. He is the veil of the angels, the cipher of revelation and its interpreter for the children of Adam. With him are the keys of Paradise, which none enters but the one who obeys him, and with him is the passage from the Fire, which none enters but the one who disobeys him. And the people are only two men: one who has been taught the purpose of knowledge, whose soul has been quickened by the spirit of certainty, so that he is a scholar by his knowledge and a master by his work; and another, a learner upon the way of salvation. The rest of the people are savages and a rabble who know nothing, followers of every braying voice, each one lost in his own error and leading others astray by his ignorance. They imagine that they are doing well. Yet the punishments of old have already passed away before them, and God will not fail His promise, and the disbelievers shall have the like of it.&quot;</p>
<p>The boy said: &quot;So this is what virtue is, and this is what knowledge and its unfolding are. Blessed are the friends of God, and blessed are those who follow them in doing good. Will I reach this great station by way of the stations that lie beneath it?&quot;</p>
<p>The Master said: &quot;Far from it, O my son. That is a station God has honored above all stations and degrees, so that none attains it except by excellent work. If you do its work and strive its striving with truthful certainty and a pure, mindful heart, I hope that you will attain of it what the chosen friends of God, the righteous, have attained.&quot; The boy said: &quot;And who can hope to reach the like of this station by which God has raised His friends?&quot;</p>
<p>The Master said: &quot;Their God is your God, and between God and anyone there is no kinship; nothing brings the creation near to God but piety and righteous work. As for the knowledge by which God has raised His friends, you stand at its beginning; if you act upon it, you will reach its end. It is binding upon God to bring you to the reaches of the righteous among them, and He will not withhold from you anything of what He gave them.&quot;</p>
<p>The boy said: &quot;Can you help me to that, as the first favor came from you?&quot;</p>
<p>The Master said: &quot;This is a station in which nothing avails but the work of its own people.&quot;</p>
<p>The boy said: &quot;How can that be, when it was granted to you before?&quot;</p>
<p>The Master said: &quot;The sower can make the earth good, and sow, and water it, but he cannot bring forth the plant and the buds. A man may bring forth his seed whenever he wills, but he cannot fashion from it what he wills. So it grieves me, O my son, that you should seek my help in a thing to which I cannot help you. May God open your breast and light your heart with guidance. So keep the fear of God and do good, for God does not waste the reward of one who does good work. You are upon the path of salvation, the way of guidance, the road of the people of piety — your own path, the one at whose beginning you stand. Hold fast to the rope to which you have been called, until you are guided by a rope from God to the rope of God, for that is the goal of the seekers.&quot;</p>
<p>The boy said: &quot;Is the rope of God not the Imam to whom you have called me?&quot;</p>
<p>The Master said: &quot;He is its outward sign. He is your rope and the most trustworthy handhold, your hujja (<span class="ar-inline" dir="rtl" lang="ar">الْحُجَّة</span>), your proof, and the door of your Imam.&quot;</p>
<p>The boy said: &quot;Then what is the rope of God, and what is the rope that comes from God?&quot;</p>
<p>The Master said: &quot;That is the end of your guidance and the utmost of the worlds.&quot;</p>
<p>The boy said:</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ</span></p></blockquote>
<p>&quot;There is no might and no power except by God. He who has no guide has drowned in the depths of ignorance, just as he who has no ship has drowned in the seas of the world.&quot;</p>
<p>The Master said: &quot;And what are the might and the power you have mentioned, which cannot be except by God?&quot;</p>
<p>The boy said: &quot;We mean: I have no stratagem to draw a benefit to myself, and no power to ward off from myself a harm I dislike, except by God.&quot;</p>
<p>The Master said: &quot;Then why do you say there is no might (<span class="ar-inline" dir="rtl" lang="ar">اَلْحَوْل</span>), and not there is no stratagem (<span class="ar-inline" dir="rtl" lang="ar">حِيلَة</span>)?&quot;</p>
<p>The boy said: &quot;It is narrated to us in our sciences that hawl is the year, by the words of God,</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">حَوْلَيْنِ كَامِلَيْنِ</span></p></blockquote>
<p>two complete years, meaning two years. And we have it narrated, as the common people too have transmitted, that quwwa, power, means mules, by the words of God,</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">وَآتَيْنَاهُ مِنَ الكُنُوْزِ مَا إِنَّ مَفَاتِحَهُ لَتَنُوْءُ بِالْعُصْبَةِ أُولِي القُوَّةِ</span></p></blockquote>
<p>And We gave him of the treasures such that the keys of them would weigh down a band (<span class="ar-inline" dir="rtl" lang="ar">عُصْبَة</span>) of men possessed of power. They said: the usba is forty men, and the quwwa is the mules; and the keys of his treasures were the load of forty mules.&quot;</p>
<p>The Master said: &quot;So it is as if, by your words there is no might and no power except by God, you meant there is no year and no mules except by God? Is this the interpretation of your saying and its meaning?&quot;</p>
<p>The boy said: &quot;I have no saying other than this, yet it is weak, and it resembles nothing of the words of wisdom. Indeed I reckon that the meaning within it is other than this, something stronger in speech and firmer in the mind. Do the two words have an inward interpretation other than this?&quot;</p>
<p>The Master said: &quot;Creation has uttered no word of truth but that it has a root in the inward, and there is no false word but that it once had a meaning. When speech is turned away from its meaning it becomes impossible, and the impossible, moved from its place, is altered, and the truth, when it is altered, becomes falsehood. It is only a speech by which what comes after is grasped through analogy and forms, just as what came before was grasped through likeness and parables.&quot;</p>
<p>The boy said: &quot;I am convinced. So what is the meaning of the two words and their like?&quot;</p>
<p>The Master said: &quot;As for al-hawl, he is the speaking Imam of God and His truthful Caliph, the lord of the twelve captains, just as the hawl, which is the year, is completed only in twelve months. The Imam is named hawl because he turns (<span class="ar-inline" dir="rtl" lang="ar">يحوّل</span>) the speech of the Creator, in the subtlety of its essence, into the speech of the children of Adam, until it is understood and becomes outward speech; and so the words of wisdom take on a body and a frame, while the speech of the Creator holds within them the spirit of life and the light of salvation. The excellence of the words of wisdom over all other speech is by the excellence of the speech of the Creator that is their inward. So the Imam is named the hawl for this turning of speech, and he does not turn it except by the permission of God. And quwwa, power, is his hujja and his door, whom God has strengthened to bear the heavy burden of utterance. He takes the speech from the Imam in summary and distributes it among the callers (<span class="ar-inline" dir="rtl" lang="ar">الدُّعَاة</span>) in detail, each according to his station. So the hujja is named quwwa, for it is strengthened only by God. Therefore whoever says there is no might and no power except by God means: there is no Imam and no hujja except by God, and from God come their light and their sustenance. And the usba, those possessed of power, are the twelve hujjas. Likewise Joseph (<span class="ar-inline" dir="rtl" lang="ar">عَلَيْهِ السَّلَامُ</span>) said to his father:</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">يَا أَبَتِ إني رأيْتُ أَحَدَ عَشَرَ كَوْكَباً وَالشَّمْسَ وَالقَمَرَ رَأَيْتُهُمْ لِي سَاجِدِيْنَ</span></p></blockquote>
<p>O my father, I saw eleven planets, and the sun and the moon; I saw them prostrating to me — meaning by the sun the Imam, by the moon his hujja and his door, and by the planets the completion of the twelve captains. And likewise the brothers of Joseph said:</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">لَيُوسُفُ وأَخُوْهُ أَحَبُّ إلى أبينَا مِنَّا وَنَحْنُ عُصْبَة</span></p></blockquote>
<p>Truly Joseph and his brother are dearer to our father than we are, though we are a band (<span class="ar-inline" dir="rtl" lang="ar">عُصْبَة</span>) — meaning the twelve captains: let him choose out a man from among us. So there entered upon them in this a failure of right judgment concerning Joseph (<span class="ar-inline" dir="rtl" lang="ar">ع</span>), and the risings of envy toward him appeared in them when God favored him. Yet the command of God was fulfilled in Joseph, and the outcome of their affair was remorse and repentance before him.&quot;</p>
<p>The boy said: &quot;Praise be to God, who cleansed them of impurity and returned them to the return of repentance and the ways of turning back. What, then, is the meaning of the king''s saying,</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">إني أَرَى سَبْعَ بَقَرَاتٍ سِمَانِ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعَ سُنْبُلاَتٍ خُضْرِ وَأَخَرَ يَابِسَاتٍ</span></p></blockquote>
<p>I see seven fat cows being eaten by seven lean ones, and seven green ears of grain and others dry? What are they, and what is the dream-vision in sleep?&quot;</p>
<p>The Master said: &quot;As for the dream-vision, it is like the outward when a work is done — like the mirage that, when one comes upon it, one finds to be nothing. So too is the work of the outward without the inward: nothing of it is accepted, however much there may be. And likewise the vision in sleep: nothing is realized from what is seen, however often it is seen. So the king said I see, in the account of the common people, seven things turning upon seven. As for the seven fat cows, they are the causes of God that stand between Him and His creation. As for the seven lean ones, they are the seven appointed speakers (<span class="ar-inline" dir="rtl" lang="ar">النُّطَقَاءُ</span>) who are driven by need to what comes from God at the hands of His seven causes. And the seven green ears are causes between God and the guardians (<span class="ar-inline" dir="rtl" lang="ar">أَوْلِيَاء</span>). And the seven dry ones are the guardians, driven by need to what comes from God at the hands of these seven causes. So blessed be God, Lord of the worlds.&quot;</p>
<p>The boy said: &quot;And what is the like of this among us?&quot;</p>
<p>The Master said: &quot;That is in the foundation of Islam, and its child is like a grain that sprouted seven ears — meaning that seven imams came out of his loins.&quot;</p>
<p>The boy said: &quot;How, then, did God forbid the world, saying,</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">فَلا تَغُرَّنَّكُمُ الحَيَاةُ الدُّنْيَا</span></p></blockquote>
<p>Let not the life of this world deceive you?&quot;</p>
<p>The Master said: &quot;God has spoken truly. He did not say, Let not the world deceive you. He said, Let not the life of this world deceive you. Life has four meanings: a life that is outward in this world, whose end is annihilation, and the life of the Hereafter, whose end is permanence. He said: do not work for the perishing life; work for the lasting life. This is His saying,</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">يَا لَيْتَنِي قَدَّمْتُ لِحَيَاتِي</span></p></blockquote>
<p>Oh, would that I had sent something forward for my life — meaning, would that one had sent forward, in the perishing life, something for the lasting life. And the two lives, in another sense, are a life by the knowledge of the outward and a life by the knowledge of the inward. The knowledge of the outward is the life of this world, and it is the lower knowledge; the knowledge of the inward is the life of the Hereafter. For this reason He said, Let not the life of this world deceive you — meaning: let not the outward of knowledge, and acting upon it alone, deceive you. For He will not accept it of you except with the inward established together with the outward, and He does not accept the outward without the inward.&quot;</p>
<p>The boy said: &quot;What of one who knows the inward knowledge but does not know the outward and does not act upon it? What is his standing among the people of religion?&quot;</p>
<p>The Master said: &quot;A wretched station. For then his inward does not stand, nor is it made sound, when he abandons a thing he was commanded to do — a thing he was to make a shield for his inward. He is like the outward of fruits: if the rind is peeled from them before their harvest, they spoil and are not made good afterward; and like the body: if its limbs are severed, the soul is not sustained in it for a single hour. Such is the outward of religion: if its obligations are neglected, its inward does not stand for its owner. And his leaving the outward, without the permission of the one who imposed it upon him, does not escape one of two traits: if he left it out of incapacity, he is more incapable still of the inward; and if he left it deliberately, having the power to keep it, he is disobedient to the one who commanded him. The disobedient is a transgressor, and the transgressor does not dwell as a neighbor to the friends of God; rather he is their enemy and they are his enemies, because he has severed what God commanded to be joined.&quot;</p>
<p>The boy said: &quot;And one who knows the outward knowledge and acts upon it but does not know the inward? What is his standing among the people of religion?&quot;</p>
<p>The Master said: &quot;A worse station, for he is like a body that was formed but into which no soul was breathed. He is counted among the dead, and death is the station of the disbelievers; and one who disbelieves in the signs of God is an enemy to religion and its people.&quot;</p>
<p>The boy said: &quot;So I see that the outward is not made good except by the inward, and the inward does not stand except by the outward; and that the world is not lawful except for one who knows the Hereafter, which is its life and its inward. Likewise religion is not made complete for its people until they establish both its outward and its inward.&quot;</p>
<p>The Master said: &quot;Yes, this is the meaning, and upon this is the work. For to establish all that God has commanded is to merit His good pleasure, and to abandon any of what God commanded is to expose oneself to His wrath.&quot;</p>
<p>The boy said: &quot;Then is not one who knows the outward together with the inward and establishes them both a believer?&quot;</p>
<p>The Master said: &quot;Yes, he is a true believer.&quot;</p>
<p>The boy said: &quot;And is not one who has knowledge and then works for the Hereafter granted a good world, its good things made lawful for him and the turning about in its gains?&quot;</p>
<p>The Master said: &quot;Yes. The world is not made good except for them, and they are the most deserving of the world and the worthiest of it.&quot;</p>
<p>The boy said: &quot;Then why do I see the people of this description — the scholars among the people of this affair — having rejected the world and all that is in it, until the ignorant among them suppose that it is forbidden to them, turning away from this world, seeing it only askance, their souls finding it heavy? And why do I see their colors yellowed without illness, their bodies weak, their skins clinging to their bones, until it is as though they do not eat food, though they do eat?&quot;</p>
<p>The narrator said: When the Master heard the mention of his brethren and this description of them, he choked with tears and his eyes overflowed, and for a time he could not speak from the intensity of his weeping. And the boy wept at his weeping, until the Master feared that some of their enemies might overcome them. So he restrained himself, and his heart grew calm within him, and then the Master turned to the boy.</p>
<p>The Master said: &quot;O my son, the people you have described in this way looked upon themselves by the light of life and busied themselves in their affair with the certainty of salvation, and they were not harsh upon themselves. O my son, the world is seen by wealth and children, and the Hereafter is seen by knowledge and certainty. O my son, the faith of these people in the unseen is sound, so they were certain of the promise and the warning; their souls yearned for what they were promised, so they sought it, and the fear of the warning alarmed them, so they labored, and they feared the drunkenness of death, so they hastened to good deeds. Their bodies grew weak from the persistence of fasting, and their colors yellowed from the length of vigil. They do not sleep with the sleepers, out of dread, nor do they eat of their sustenance except with a bitter reluctance. The desires of thought have distracted them from the pleasure of living, and the sweetness of remembrance has kept them from the respite of sleep. Their souls have turned away from the desires, so the world is not sweet to them; they remember death often, so life is not pleasant to them; they have seen the bounties of the Hereafter with certainty, so they see the world only askance. So they refused the world as men occupied away from it, without holding it forbidden.&quot;</p>
<p>The boy said: &quot;This is the true report, and in this sense was the scholars'' aversion to the world, while the people are heedless of them, supposing that they have forbidden to themselves what God made lawful for them. So describe to me the deception of the people of the world by their world, and their heedlessness of the Hereafter.&quot;</p>
<p>The Master said: &quot;If those enamored of the world would reflect upon their own creation and the turning about of their states — from weakness to strength and from strength to weakness, from bliss to passing away and from life to death — and would then look upon those who passed before them of the vanished generations, among whom were the good and the wicked who went alike to one dust, seeing no reward for the good in this world nor punishment for the wicked in this world, they would know that they were created for other than this world. But earning weighed heavily upon them, so they did not take upon themselves the burden of the search. So they took the trifle of this lower world and were content with the bliss of the world in place of the Hereafter. This is their way, and this is their meaning. They have no argument before God, and no ground of reproach against His friends, and there has already come to them of the tidings that which holds a deterrent.&quot;</p>', 3476);
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('the-master-and-the-disciple', 'the five shares and the long road to the shaykh', 8, '7. The Five Shares and the Long Road to the Shaykh', '<p>Praise be to God, the boy said, who has guided us to His religion, for we could never have found the way without His favor. Now tell me about the beginning of this creation and how it is put together. Is it a single creation, or one that differs from itself? For I see so much difference among people, in their opinions and in their desires.</p>
<p>The Master said: As for the creation of bodies, it does differ, as you can see in the variety of tongues and colors. That variety is a proof of His power, made plain through His signs, so that created beings may know one another — a child knowing his father and a father his son, a man knowing his own wife and no other, a woman her own husband and no other. So God created them. But as for the creation of the instrument — that is, the senses, both what is visible of them and what is hidden — it is a single creation, and what is visible tells you about what is hidden. Have you ever seen a scholar with three eyes, so that his surplus of knowledge showed on him, or an ignorant man with a single eye, so that his lack showed on him — such that one might say the scholar saw because he had more and the ignorant man failed to see because he had less? Have you ever seen the outward instrument of one man exceed that of another? No — you see their creation as nothing but a single, even creation in the visible instrument, and the sense of the composition is one and the same. From this we know that the inner senses follow the very same pattern. This is justice. God would not be just in what is visible and unjust in what is hidden. He gave the scholar no second heart in one breast, nor did He rob the ignorant man of anything. The instrument is one, and the composition belongs to the One who gathered it. By this very thing God has argued against them — by the instrument He gave them and which they failed to use. The Almighty said:</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">لَهُمْ قُلُوبٌ لَا يَفْقَهُونَ بِهَا وَلَهُمْ أَعْيُنٌ لَا يُبْصِرُونَ بِهَا وَلَهُمْ آذَانٌ لَا يَسْمَعُونَ بِهَا</span></p></blockquote>
<p>They have hearts wherewith they do not understand, and they have eyes wherewith they do not see, and they have ears wherewith they do not hear. Do you imagine that God, in His bounty and His generosity, laid upon them a charge they had no power to bear and carry? No. He is fairer than that.</p>
<p>The boy said: I see it no other way, and I would not claim otherwise. But I ask you about the difference of desires. Where did it come to them from, when the instrument is sound and the origin of the composition is one?</p>
<p>The Master said: As for the origin, it is one. All of them descend from Adam, and Adam is from dust, created by his Lord, who breathed into him of His Spirit. But they departed from the Sunna in their marriages. They were born on a footing other than the religion and were raised in something other than guidance. And I do not doubt that among them are the children of fornication, who claim as fathers men who are not their own. When the roots were corrupted, the branches were corrupted with them and grew strange, and the return to the truth grew hard for them — all the harder for the arrogance that had entered them against obedience, the laziness against worship, and the envy of the friends of God, so that they no longer held themselves within what is lawful or held back from what is forbidden.</p>
<p>The boy said: If the origin is one and the instrument is one, where did the desires come to differ, when the aim in seeking is one — since every man seeks what is good for himself?</p>
<p>The Master said: By my life, their aim in seeking is one, yet they differ in striking the mark, like archers aiming at a target. They agree in shooting at it with resolve and with the same instrument, and for all that they still differ in whether they hit it. So it is with the hearts within the breasts: they are gathered upon the minds, and the minds are gathered upon the safeguarding of the bodies and their dignity. When the call of truth came, they differed. Some judged that answering the Messengers and humbling themselves before them belonged to their own dignity and guarded them from folly. Others judged that denying the Messengers and setting themselves above obedience to them belonged to their own dignity and guarded them from the narrowness of worship. The origin was one — the pursuit of ease for the body and of dignity for the soul. So one party chose what the Messengers promised them of God''s reward, even though in this world it was rare and hard to reach, for the sake of its lasting. And the other party chose from the pleasures of this world, even though they perish, for the sake of their being at hand, the ease of pursuing them, and the swiftness of their reward. The very hearts by which the first sought the bliss of the Hereafter were the same hearts by which the others sought the bliss of this world. Each looks to himself, and each supposes himself a sincere counselor to himself. So they came together in the seeking and differed in the striking. That is of the justice of God, of His generosity, and of the reach of His gift: to every seeker is given from Him what he sought. Whoever desires the reward of this world, We give him of it, and whoever desires the reward of the Hereafter, We give him of it.</p>
<p>The boy said: The people of this world stand in classes within their world. Some are rich, above all labor, kings by the abundance of their wealth. Others are poor, in need of wealth, and they serve the rich to gain from them. Then does the bliss of this world gather them onto one level, so that they end up all alike in the evil of the outcome? Or is there for some of them a standing apart from the rest?</p>
<p>The Master said: It is of the justice of God that He joins them one to another and does not separate them from their companions and the people of their affection. They are equal in His punishment, just as they were gathered together in His disobedience.</p>
<p>The boy said: And what of this religion which God has honored, and perfected, and was pleased with as a religion for Himself, and made binding upon His servants? Will He accept from them a part of it without the rest, so that they stand in classes as the people of this world do? Or will He accept it only from the one who brings it whole?</p>
<p>The Master said: If the people of this world stand in classes within their world, then the people of religion stand in degrees within their religion. In justice, it is a duty that the Creator be worshipped with the fullness of what He willed. But His riches are great, and great too is their need of Him. His mercy was wide enough for them, and He knew that among them are the weak; so He accepted from them whatever came easily of sincere striving in work and of effort spent in obedience, whether little or much of it. Then He charged each one with knowledge according to his strength and his deed, and gave every man of merit his due of merit, so that they stand in degrees with their Lord. Then, by His justice, He appointed for them, as the fruit of their obedience, that He would join them to the people of the complete religion and the excellent deed among His servants. The Almighty said:</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">وَمَنْ يُطِعِ اللهَ وَالرَّسُولَ فَأُولَئِكَ مَعَ الَّذِينَ أَنْعَمَ اللهُ عَلَيْهِمْ مِنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ وَحَسُنَ أُولَئِكَ رَفِيقًا ذَلِكَ الفَضْلُ مِنَ اللهِ</span></p></blockquote>
<p>And whoever obeys God and the Messenger, those are with the ones upon whom God has bestowed favor, of the prophets, the truthful, the martyrs, and the righteous. What excellent companions they are. That is the bounty from God. This is granted them for the effort they spent in obedience. It is not that their deeds equal the deeds of the righteous, but it is a mercy from God to them, weak though they were and slight though their works were.</p>
<p>The boy said: Praise be to God, who has done this for them. Then is it to be feared for anyone that he be punished for something other than disobedience, even if his work was little?</p>
<p>The Master said: God is more just than that.</p>
<p>The boy said: Is it to be hoped, then, for anyone to enter Paradise without works — like the insane and the young children?</p>
<p>The Master said: That falls under the grace of God, His generosity, and the breadth of His mercy.</p>
<p>The boy said: Then what is the limit of effort in obedience and of sincere work at which God becomes bound to accept a man''s excuse in all the rest?</p>
<p>The Master said: The reach of his knowledge and the utmost of his strength.</p>
<p>The boy said: Then describe to me, in the duty of knowledge and of action, the goal of each, that I may measure myself against it. If I am able to reach the goal in what pleases my Lord, I press on. And if not, I halt at the limit of my strength, and God has the greater right to excuse me for what I fell short of. I am certain of the justice of God and safe from His wronging me, yet afraid of the evil of my own soul.</p>
<p>The Master said: Do not be afraid where you are safe, and do not feel safe where you should be afraid. Strive for God in the work with your self and your wealth. For God is not pleased by what He hates, nor does He hate what pleases Him. He has hated unbelief for His creation, and He is pleased by thankfulness from His servants and by justice in their ruling, and He accepts nothing else. Truthfulness and faithfulness are His two gardens, and none is saved with Him except the people of truthfulness and faithfulness.</p>
<p>The boy said: Then make plain to me the goal of the work within myself, and what God has made binding upon me in it.</p>
<p>The Master said: Obedience to God ennobles its people, however humble their origins, and the good deed is the crown of the one who does it. As for what is a duty upon you in your own self, it is to perform all the obligations and to shun all the forbidden things, for that is what sustains the religion and keeps the body pure. And the sum of what makes the pleasure of God binding for you and secures His acceptance of you is this: that you bring to another what you would love him to bring to you, and that you hold back from him what you would love him to hold back from you. In that is justice, and God is pleased with justice.</p>
<p>The boy said: Yes, this is the binding truth, and whoever does not do it has no share with God in anything. Then is there, in what you have mentioned, any room in a time of necessity?</p>
<p>The Master said: God has made room in that for His servants, out of tenderness and mercy from Him. He said:</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَلَا إِثْمَ عَلَيْهِ</span></p></blockquote>
<p>Whoever is compelled, without willful transgression and without excess, there is no sin upon him.</p>
<p>The boy said: Praise be to God, who has laid upon His servants no hardship in the religion. I am resolved to guard what I have been commanded, and I seek the help of God in what He has ordered of me. Then what is the duty regarding my wealth, which you joined to my self when you told me, Work with your self and your wealth?</p>
<p>The Master said: As for your wealth, it is whatever God has granted you of every kind of gain. Take it only from what is lawful, and spend it only in its rightful place.</p>
<p>The boy said: And what is the lawful source it is taken from, and what is the rightful place it is spent in?</p>
<p>The Master said: Its lawful source is the wholesomeness of the gains in which you have wronged no one and which you have not mixed with falsehood. As for its rightful claim, it is its zakat: that you look to all that has come into your hand, whether little of it or much, and bring out a fifth of the best of it — the dearest of it to you — and deliver it to the one whose claim upon you is binding. At that, your wealth is purified by the alms, just as your body was purified by the work. The work is a shield, and the zakat is a cleansing, and he has prospered who purifies himself.</p>
<p>The boy said: I will do it, and I turn to God in repentance for what has passed. Then what is the work in what remains of the wealth?</p>
<p>The Master said: You spend it upon yourself and your dependents with kindness. And if a surplus of it stays with you, relieve with it the people of need among your brothers, and give your kindness to everyone who turns to you seeking it, for the one who has no surplus is in need that another give to him. So be swift to every good and foremost in every act of bounty. This is the goal of the work — if you have the patience for it.</p>
<p>The boy said: Yes, I will be patient, and then patient again. And how should a man in great need not be patient toward the one who has no need of his work? Every needy man is patient, and every man given a favor gives thanks.</p>
<p>The Master, gladdened by the boy''s words, said: Praise be to God, who has granted you what is right in speech. I ask Him to help you to the completion of the deed, for that is the perfection of merit.</p>
<p>The boy said: I had been seeking, for myself, the merit of a favor from another man''s hand, and now that the merit has at last become mine from my own hand, I was on the point of denying it to myself — and I find no one more treacherous to my soul than myself. So here is all my wealth, between your hands, in five shares. One share of it is its zakat. One share is expiation for what I have squandered. One share is thanksgiving to God for what I have come to know. One share is for the poor among my brothers. And one share you are to accept by your grace, that it may be a provision for you. Gather them all to yourself, for God will send the like of them in their place.</p>
<p>The narrator said: The Master''s heart went out to the boy when he saw how plainly the boy''s true worth had come to light, and what the trial had drawn out of the fine character within him, so that his merit stood revealed and his conduct proved pure.</p>
<p>The Master said, as his tears ran down: O my son, it is for those like you that the scholars set out upon the road. It is for those like you that the earth is held firm and the sky is kept aloft. It is for those like you that the bonds of kinship are made plain, and for those like you that the rain falls from the openings of the clouds. So rejoice, O my son, in what God has granted you and in the breast He has opened to Islam. Receive the good news of a light from your Lord and an opening near at hand. Accept God''s gift to you and the good things of His favors, with abundant work and noble thanks. As for my share of this wealth, I have no need of it. I came out from wealth and fled its trial, and it would be no act of piety, O my son, for you to turn me back to what I have come to hate. As for your brothers'' share, let it remain with you. If they ask you for anything, hand it to them yourself, so that they may know your merit and give thanks for your kindness. As for the share of expiation, keep it by you until you come to know your sin. As for the share of thanksgiving, let it be a trust in your keeping for God until you reach your maturity and rise to the highest of what you have come to know. As for the share of zakat, that too is a trust in your keeping for the one to whom it belongs. So gather them all to yourself until you meet him, for he is the one who holds authority over you and on your behalf.</p>
<p>The boy said: Then who is this generous one you speak of, whose judgment you never overstep and whose command you never transgress?</p>
<p>The Master said: He is the one whose right God has made binding upon me and upon all the believers, in whose hand are the keys of the gardens and the landmarks of the kingdom, and whose palms are open wide. By the light of Sinai, he is the cause behind the signs, the one whose knowledge calls to the loftiest of ends. Through him your light is made complete; through him God brings your affair to its perfection; and at his hand you are blessed.</p>
<p>The boy said: Kindness such as this — to whom does it belong, and who are you yourself?</p>
<p>The Master said: I am his son and one of his servants in good works, seeking his pleasure and shunning his displeasure.</p>
<p>The boy said: I think myself far from his good pleasure, and yet near enough that, had I never known of him, I would have had an excuse. Do I have an excuse, now that I know?</p>
<p>The Master said: An excuse is granted only before one is brought face to face with such knowledge.</p>
<p>The boy said: Shall I speak, or shall I hold back?</p>
<p>The Master said: Say what seems best to you.</p>
<p>The boy said: Should you not, this very moment, take me by the hand to the door of his chamber, that I may enter, and to the house of light, that I may drink from it? This belongs to the full measure of the truthfulness that is binding upon you.</p>
<p>The Master said: This is your due, but only with his leave and his decision.</p>
<p>Then the Master took his leave of the boy and departed. The boy wished him to take provisions from his own store, but the Master would not accept them. He went on until he reached his own greater father, and he described the boy to him and assured him that the boy now belonged to the company of the people of goodness and to the lineage of truthfulness. The father marveled at it.</p>
<p>He said: Bring this boy to me swiftly, for I hope he will be a door of mercy that God opens for the people of his age.</p>
<blockquote class="aside bridge"><p><strong>A note for the reader.</strong> <em>In this account a teacher is also called the father of the one he guides, so &quot;father&quot; now carries three men: the Master''s own elder father here, the Master himself when the boy speaks, and the Arab chief who fathered the boy.</em></p></blockquote>
<p>The Master lingered only a little, then returned to the boy, and found his body in a state different from the one in which he had left him.</p>
<p>The Master said: What is this I see in you, unlike the state in which I left you?</p>
<p>The boy said: And what is it you have noticed in me, may my father and mother be your ransom?</p>
<p>The Master said: A weakness of body and a yellowness of color.</p>
<p>The boy said: That comes from a desolation that fell upon me after you left.</p>
<p>The Master said: What is this desolation, and what has brought on this weakness?</p>
<p>The boy said: Your absence left me desolate, and the fear of some misfortune before I could meet you again weakened me.</p>
<p>The Master said: God has known what is in your heart, and so has made the affliction light for you, and has cast into the heart of the one who has charge of you a mercy toward you. So take up your provisions for the journey, for through you I shall reach my hope, and I shall bring you to the door of your goal. There is no power except by God.</p>
<p>At this the boy was so overcome by joy and reverence that his soul all but left his body, until God, knowing his condition, took hold of him and returned it to him. When he came to himself, he said:</p>
<p>Praise be to God, who has never ceased to be merciful to the believers.</p>
<p>And he gave great thanks to his father, and reached up to kiss his palms, and then his feet. He rose at once and took up the traveling kit, and the two of them set out until they came to the greater scholar. They asked leave and were admitted. They entered, gave their greetings, and sat down at his invitation. When they had settled into the gathering, the boy said to his teacher: Teach me how to speak and how to ask for what I need.</p>
<p>The Master said to him: It is not lawful for me to instruct you in anything while you are in this place, out of reverence for its master. For you are in the hands of one who knows your need and knows what you desire.</p>
<p>So the boy held back, and they remained with the greater scholar for a time, until he had brought the boy''s affair to completion and perfected his guidance, and the boy reached the end of his hope and came to know what he possessed and what was asked of him. Then they took their leave and went out, the two of them keeping their counsel. They had spoken no words in the gathering except those of peace and good cheer, for the boy had turned yellow from the depth of his awe and could not speak. The Shaykh, the lord of the house, gave orders that the two be treated well and honored, and that whatever they needed be provided. He then went along with them to his house, and when he had brought them inside he greeted them and showed his gladness at their coming.</p>
<p>He said to the Master — for the two of them were friends, and between them lay brotherhood and a long acquaintance: Brother, is this the boy we used to hear of?</p>
<p>He said: Yes, this is the one whose report has grown sweet in men''s hearts, so that the mention of him has risen upon the tongues of the believers.</p>
<p>The boy said: Has the report of my story truly reached the friends of God, so that they speak of me in their gatherings?</p>
<p>The Master said: Yes, my brother, so it is.</p>
<p>The boy said: Favors have gathered round me from every side, and bounties have overtaken me from every path. I do not know whom to thank, nor whom to repay.</p>
<p>Then they all sat together and talked through the night. When morning came, they asked leave to enter upon the Shaykh. Once they were admitted and had finished their greetings, the Shaykh gave them leave to sit, and they sat. Then the Shaykh began to speak.</p>
<p>He said: Praise be to God, who has opened with His light the hearts that were sealed, and unlocked with His justice what was closed against the seeker, and made remembrance easy by His craft, as a gentleness to His servants and a mercy from Him to those who long for Him. He has not burdened His creation with the full measure of what is due to Him, nor has He been content that they deny His blessings. Rather, out of His justice, He has charged them only with what they are not too weak to bear, so that the matter was set level between two extremes, and for that reason was called justice. He has spread His hands wide with bounty in kindness and grace, and has not disappointed one who calls upon Him, nor deprived one who keeps silent. His blessings overflow and His favors abound, neither reserved for the one who gives thanks for them, for the greatness of His reward, nor withheld from the one who is ungrateful for them, for the greatness of His punishment. He has held His blessings too noble to be stinted, and made His proofs too well established to be denied. He is too vast in His encompassing to be contained within existence, and too high in His evidences to be met with rejection. He is present without being bounded, and known without being described. Glory be to Him. How great is His gentleness to His creation, how merciful is His might toward His servants, how just is His rule for all His power, how near is He to His people for all His loftiness, and how far above all illusions for all His nearness. So worship Him and give thanks to Him. To Him you shall return.</p>
<p>Then he said: Now to proceed. It is among the honors of minds that they be put to use in seeking, and among the fruits of seeking is finding, and among the marks of finding is the sweetness of what is found. Every sweet, fresh spring has a surface that is drunk and a depth that lies veiled. The one who seeks it never wearies of the thought that pursues it, and creation never reaches the end of its purpose. Its marks are truth, and the truth of the truth is an obligation, and from this it was named truth, for the establishing of its obligation. Whoever withholds from the truth what is due to it is a wrongdoer. Indeed, among the rights of thought is the purifying of hearts by good manners, and among the rights of good manners is the seeking of knowledge, and among the rights of knowledge is acting upon it, and among the rights of acting upon it is that it be kept pure by obedience to those charged with authority, and among the rights of obedience is that it be carried through in hardship and ease alike, in good fortune and in trial the same.</p>
<p class="ar-block"><span class="ar-inline" dir="rtl" lang="ar">وَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُوا۟ وَمَا يُلَقَّىٰهَآ إِلَّا ذُو حَظٍّ عَظِيمٍۢ</span></p>
<p>And none is granted it except those who are patient, and none is granted it except one of great fortune.</p>
<p>Then he turned his face toward the boy and said: O young man, you have been honored as an intimate come to visit, and greeted as a guest who has set his course here. So what is your name?</p>
<p>He said: Ubayd Allah (<span class="ar-inline" dir="rtl" lang="ar">عُبَيْدُ اللَّهِ</span>, little servant of Allah), son of Abd Allah (<span class="ar-inline" dir="rtl" lang="ar">عَبْدُ اللَّٰه</span>, servant of Allah).</p>
<p>The Shaykh said: That is your description, and your report has already reached us.</p>
<p>The boy said: I am free, son of Abd Allah.</p>
<p>The Shaykh said: And who freed you from a master, that you should be free? The boy said: This scholar freed me — and he pointed with his hand to the Master who had summoned him.</p>
<p>The Shaykh said: Consider now: if this man were himself owned and possessed nothing of his own, would his freeing of you be valid?</p>
<p>The boy said: It would not be valid.</p>
<p>The Shaykh said: Then what is your name?</p>
<p>At this the boy bowed his head, at a loss for an answer.</p>
<p>The Shaykh said: O young man, how can a thing know that which has no name? The boy said: Then I am one newly born to you — so name me.</p>
<p>The Shaykh said: That waits until seven days are complete.</p>
<p>The Shaykh said: For the honoring of the newborn.</p>
<p>The boy said: And if the newborn dies before the seven days are complete?</p>
<p>The Shaykh said: No harm comes to him. He is named after that.</p>
<p>The boy said: And this name by which you will name me — is it mine?</p>
<p>The Shaykh said: Would you then become one that is worshipped, though you were born?</p>
<p>The boy said: How, then, is the matter of it to be stated?</p>
<p>The Shaykh said: The name belongs to you, and you belong to the name. So do not step beyond your bound, and take your leave until your term.</p>
<p>So the boy rose in haste, in the goodness of his obedience, and made no reply, in the goodness of his manners. He went out, and his father went out with him, until they returned to their lodging. The owner of the house greeted them.</p>
<p>He said: How does this brother of ours stand concerning his need?</p>
<p>The Master said to him: A promise has been made, and the one promised is thirsty, and the term is near.</p>
<p>So they stayed until the seventh day. Then they asked leave of the Shaykh, and when he had granted it, he ordered the boy to wash and to put on his purest garments. As the boy set about the preparation, his heart sensed that his need would be granted that day, and that this preparation he had been ordered to make pointed to some good that would follow it. When he had done what he was ordered, they all went out. The boy went out saying, A day of fortune, and a patron of fortune, repeating it over and over. Nothing moved him to this saying but the fullness of his joy and the depth of his longing to know what would bring him nearer to the pleasure of God. When they came in upon the Shaykh, they found that he had taken up the implements of his work. He greeted them with peace, and they returned the greeting.</p>
<p>Then the Shaykh bade the boy draw near, and he drew near; the Shaykh drew him closer, and he came close. And he began to speak of matters that no imaginings had ever encompassed, that no pens had ever traced, that had never crossed the heart of any human being — matters not to be named in the assemblies of preachers, nor spoken openly in the gatherings where books are read aloud, for the greatness of their excellence, matters unveiled to none but their own people. When he had discharged his duty toward the boy, and led him out of the wildernesses of his bewilderment to the very end of guidance, the boy''s path became pure and his drink became sweet, and he came to know his Lord. So he released his pilgrim state by magnifying the sanctities of God, took hold of the firm rope, circled the ancient House, completed his rites with remembrance, and fulfilled his pilgrimage by the greatest sign.</p>
<p>After that the boy and his father kept coming and going to the Shaykh, studying what he had been given, and the boy held fast to his perseverance. He never wearied of asking, so noble did he find it, nor was he ever sated with the answer, so sweet did he find it. And so they remained for a span of time, until the Shaykh knew that the boy''s root had been watered and his branch had climbed high.</p>
<p>Then the boy said to the Shaykh, in thanks to Allah and to him: Praise be to Allah, who has made you worthy of this station, so that through you He revives a religion and puts an end to an ignorance, and who has made you a place of return for the people and a sanctuary for them. You are the gate of the people of heaven and the ascent of the people of the earth. From the light of your might the lights appeared, and from the pouring of your palm the rivers flowed. May you remain so, until the one who is pleased with you is made pleased.</p>
<p>The Shaykh said: As for you, may Allah bless you in what He has given you, and aid you by His enabling grace to guard what has come to you, and set you rightly to work in His will, and smooth your way with the light of His guidance, and open your breast with the keys of wisdom, and ennoble your affair with the path of the call, and perfect your excellence with the confirmations of response, and bring you, in obedience to Him, to the best of your hope in His good pleasure. I bid you farewell, my son, and I give you leave to go. Your parting grieves me, but three considerations have forced it upon us. The first is that we are setting out on a journey to another land. The second is your separation from your family through all this time, together with the burden you took upon yourself in leaving without your father''s permission, for in him there is a heavy grief and a great anger that nothing will dispel but your return — yet I have hope for your father, if you are gentle with him. And the third is the duty of fulfilling the right of this grace that has reached you, for it is incumbent upon you to serve God by it and to call others to it.</p>
<p>The boy said: Your parting is a sorrow laid upon me, and your loss a diminishment of me. But your counsel guides the more surely, your command binds the more firmly, and your judgment is the more sound. So lay upon me what you see fit, dismiss me when you will, and be gracious enough to send my father with me to my land, that I may lean upon him in my work and entrust all my affairs to him.</p>
<p>The Shaykh said: I shall do that, and I enjoin upon you the fear of Allah who created you, and the guarding of the trust you have taken upon yourself, and the safeguarding of your father, who raised you when you were small and toiled long over your affair, with his person and his wealth. So do not clothe him in the garments of disdain, nor set him upon the vehicles of ruin. Do not slight his name, nor turn your speech away from his remembrance, nor betray him in your city. And at the outset there is room enough for you.</p>
<p>The boy said: May Allah reward you with good, as a patron of grace, on behalf of every grateful one; and may the Lord of abundance repay you for your shepherding of us, on a day when hands are too weak to repay you. I will keep your commandment. So do not cut off my share of the blessing of your supplication.</p>
<p>Then they rose, clasped hands, and embraced, and each bade his friend farewell, unable to hold himself together under the weight of the parting, able to speak only by gesture. Then they went their separate ways.</p>
<p>So the Master and the boy set out together, and when they had drawn near to the boy''s city, where his father was, the Master said to the boy: &quot;O my son, I have understood the will of the Shaykh, and you have not. Guidance lies only in his words. This is your city, and we have reached its edge. So sit with us here, off the road, for I wish to remind you of some of my concerns and to charge you with what you should do.&quot;</p>
<p>When they had sat down, the Master said: &quot;O my son, I know your father and his enmity toward the people of this matter. Added to it now is your going out with me and your absence from him without his leave and without his trust. I wish to honor your father''s view by keeping some of these affairs concealed, so that you may return to him, and he may be at ease once more, and stay near us. And I hope, if you are gentle with him, that he will be closer than anyone else to what you desire. Your absence has worn him down, and his solitude has come to frighten him. Know, my son, that Allah has opened to you, for the least of your striving, what I did not suppose you would reach until a long stretch of time had passed. Allah has been good to you, so be good to yourself, and honor the one through whom Allah has honored you. We have thought well of you, and our hope in you has been great. So keep the trust your father entrusted to you, and stand firm in your affair. Piety and wary devotion are the mainstay of your religion and your work; thanksgiving and patience are an increase to your light. Ask of Allah the opening of your provision and the goodness of His granting you success.&quot;</p>
<p>Then the Master said: &quot;I commend to you six qualities: that you trust in Allah when you are resolved; that you speak with a ruling when you are called upon; that you do not grow angry when you are wronged; that you do not weary when you are slandered; that whoever answers your call to the good, you bear with him patiently; and that you keep for yourself the best of that to which you call others. For Allah will help you and open the way before you.&quot;</p>
<p>The boy said: &quot;May Allah reward you with three goods: an imam whose case you have upheld, a trust you have counseled well, and a dead man whose life you graced with your kindness. My heart is full, and my breast is packed with light and gladness at the greatness of what you have laid open to me. I do not know which of your words is the finer: the outward, which you arranged in its sequence, or the inward, whose meanings you expounded.&quot;</p>
<p>The Master said: &quot;Praise be to Allah, who has made His way easy for you, brought its far reaches near to you, and helped you to bear its weight. I take my leave of you now and turn away from you. Is there any need still left?&quot;</p>
<p>The boy said: &quot;The pillars of my needs are three: a need already fulfilled, a need I hope for, and a need I ask you to grant of your kindness.&quot;</p>
<p>The Master said: &quot;I have understood your three needs, and I answer you concerning what you have asked. As for the need already past, it is your life in knowledge after death. May Allah bless you with a life in it and grant you the best of what you intended. As for the need for which you hope, it is to act upon what you have come to know and to accept it when you are brought to account. May Allah bring that about for you by His mercy. As for the need you ask of me, it is as though you have desired an increase upon what you have heard.&quot;</p>
<p>The boy said: &quot;There is no increase greater than your knowing what is within me. So grant of your kindness what you see fit.&quot;</p>
<p>The Master said: &quot;As for my knowing what is within you, none knows the unseen but Allah. But the believer sees by the light of Allah: <span class="ar-inline" dir="rtl" lang="ar">الْمُؤْمِنُ يَنْظُرُ بِنُورِ اللَّهِ</span> the believer sees by the light of Allah. As for the increase, I will lay its matter out plainly for you and set you upon the foundations by which you are to work. You are to take all these things whose outward form I have described to you, and turn them into parables. Whatever among them is praiseworthy is a likeness of the truth and its people — its noblest standing for their noblest, its tokens pointing to them. And whatever among the parables is blameworthy, I have turned upon the enemies of the truth and its people — its greatest for their greatest, its least for their least, its tokens pointing to them. These are the foundations of the science upon which action turns. If you preserve them, you will have need of none besides them. And I commend to you the fear of the One who created you when you were nothing, and the keeping of His covenant, and the fulfillment of the right He has laid upon you and upon all His creation.&quot;</p>
<p>When he had finished his discourse, and brought him to his place of safety, and completed his nurture of him, he said: &quot;O my son, take care of yourself, for I have a work other than you, and this is the parting between me and you.&quot;</p>
<p>At the mention of parting the boy gave a gasp so violent that he almost took his own life, his spirit near to taking flight and his soul near to leaving his body. Then he bent to kiss the Master''s feet and wiped their dust upon his cheeks, and bade him farewell and departed. The boy returned to his house, his heart torn from him in dread, unable to hold back a single word of his grief at parting from his elder father, and from the father who had been the cause of his grace, until his family and his neighbors grew afraid for him. He passed his day and his night restless with sorrow and alarm. Then his father came in upon him, in anger.</p>', 7113);
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('the-master-and-the-disciple', 'homecoming, the father, and the debate with abu malik', 9, '8. Homecoming, the Father, and the Debate with Abu Malik', '<p>The father said: &quot;My son, is this how a son repays his father? I taught you nothing but the best a father can teach a child. You never renounced yourself or your beliefs — not until I had grown old and this stranger appeared. Then you brought him in against me, and you crossed over to his cause without ever consulting your own parents. If what I held was true, you have wronged me to the very depths of my soul, for you kept the truth hidden from me. And if it was false, then you have disobeyed me and rushed toward your own ruin — and whatever calamity has struck him has now, through you, struck me as well.&quot;</p>
<p>The boy said: &quot;My father, I have shown you nothing but tenderness and compassion. You raised me out of mercy and provided for me, favoring me above kin and wealth. I have no wish to be so ungrateful, in these days of ours, that I would fail you in either of the two forms of gratitude I owe you.&quot;</p>
<p>The father said: &quot;What is the difference between the two?&quot;</p>
<p>The boy said: &quot;Either you permit me to offer you my courtesies and kindnesses, since I am your son, whom you raised from childhood and who now guides us to Allah; or you grant me leave to debate with you openly and speak my mind, so that I am safe from your anger and can draw freely upon your understanding.&quot;</p>
<p>The father said: &quot;As for an outward courtesy while our hearts differ within — that is a standing reproach between us. How long can an outward agreement hold when its very foundations are at odds? I do not want it. But your debate and your candor — those are yours. So say whatever seems best to you.&quot;</p>
<p>The boy said: &quot;In these forty years I have stood beside you, have you ever found me to be anything but one of two things? Either you are a scholar who withheld from me the teaching I was owed — and then do not blame me if you would forbid me to seek my salvation elsewhere — or you are unlearned, in which case you are excused in my eyes, yet you needed a man who was a stranger to me. I went ahead of you to him because of your age and your late years, for I have heard his words just as you have heard them, and I have seen what you have seen.&quot;</p>
<p>The boy''s words tore at his father''s heart. He saw that there was no escaping any of these arguments, and his eyes brimmed with tears. He said: &quot;My son, the argument raised against me is yours to make. You would have met the same fate as I, had you kept your affairs hidden from me. Set this to my account: if it is true, I will accept honor from you for my own sake; and even if it is false, I have laid it aside for your sake, out of compassion for you.&quot;</p>
<p>So they debated across many sittings, and they opened their hearts to one another at length, until they were guided to the straight path — living by the religion of Allah, upholding it, holding fast to it, calling others to it, and aiding one another in it. Through them Allah revived many of His creatures. The boy sent word to the Master, bringing him the glad tidings of his father''s rightness and asking him to come; so he came to them and was a cause of good for them. Allah blessed the people of that country through them and at their hands. Allah''s command was carried out, and slander came to nothing. The boy''s name was Salih (<span class="ar-inline" dir="rtl" lang="ar">صَالِح</span>, the righteous''), and his father''s name was al-Bakhtari (<span class="ar-inline" dir="rtl" lang="ar">اَلْبَخْتَرِي</span>). The two were honored, raised above others, and given high standing for the excellence of the manners they had acquired. Word of them spread through the land, and word of their religion along with it, until it reached a party of people who clung to the old creed. Al-Bakhtari had long held influence among them, and they feared that his leaving their religion would cut it off from them. So they set out and gathered before one of their scholars, called Abd al-Jabbar Abu Malik, whom they had named — for his scrupulousness, the depth of his forbearance, and his defense of his religion — &quot;Kab al-Ahbar (<span class="ar-inline" dir="rtl" lang="ar">كَعْب اَلْأَحْبَار</span>).&quot; Among them he stood eminent for his knowledge, his grasp of speech, and his discernment of opinions. When they came in to him,</p>
<p>they said: &quot;Abu Malik, do you not see what the boy has gone over to?&quot;</p>
<p>He said: &quot;Which boy?&quot;</p>
<p>They said: &quot;Salih ibn al-Bakhtari.&quot;</p>
<p>He said: &quot;And what has he gone over to?&quot;</p>
<p>They said: &quot;We are telling you that a stranger has come to the country, a man of fine speech, with a doctrine he calls people to, and we do not know what it is. The boy went to him and left with him, without his father''s leave, and was gone for a time. Then he returned to his father, speaking the stranger''s words and calling to what the stranger called for. We are told that his father has taken up his view and backed him in it. We are grieved at what they have done, and at our own holding back from them, for three reasons. First: there was a kindness of his that reached us on his father''s account, together with all you know of the brotherhood in religion between us — and we fear estrangement after closeness, and we hate division after brotherhood. Second: if these people are upon the truth, then we have fallen short in following them in it and in helping them. Third: if they have gone astray in it, then we have fallen short in turning them back from it and in upholding the truth and its people. You are the head of our religion and one of our standards, and we have come to inform you and to seek your counsel, and we will not overstep your judgment.&quot;</p>
<p>Abu Malik said: &quot;Go gently, for this speech of yours has alarmed me. You know that al-Bakhtari and his son were among those we counted as people of forbearance and scrupulousness, and that they have rights over us and old favors to their credit. You have said about them what you have said, and you are, in my regard, among those who do not turn from truth to anything else, so that Allah has made you independent of that. This is news that has reached a people, and its proof has grown plain to them, so they have followed it and been content with it. We cannot rule them mistaken and so wrong them, nor rule them guided and so wrong ourselves by imitating them; nor can we say they have been deceived and so reject them without knowing them, for they stand nobler than that in our eyes. What we must do is look upon this news with a fair eye, in the light of justice, and with a steadfast mind. For it has been said:</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">مَنْ تَثَبَّتَ فِي الْأُمُورِ لَمْ يَزَلْ سُلْطَانُهُ مَحْرُوزًا، وَمَنْ عَجَّلَ فِي أَمْرِهِ لَمْ يَأْمَنْ زَلَّةَ قَدَمِهِ</span></p></blockquote>
<p>He who is steadfast in his affairs keeps his authority secure, and he who is hasty in his affair is not safe from a slip of the foot. A breach in anything else admits of repair, and what has spoiled in it can be replaced — like a flaw in food, whose harm is slight and whose remedy is near. But a breach in religion is a grievous harm and a ruinous loss; its flaw cannot be mended, nor can anything be taken in its place — like a breach in the medicine itself, which neither frees its owner nor lets him restore his own soul. We have been told in this that the best of provisions are the treasures of the heart and the acquiring of manners, whose fruits and outcomes are praiseworthy; and among their fruits is the practice of forbearance. Forbearance is the crown of the learned; by it, noble aims raise them to the summits of glory, their merit is made plain in every place, and honor comes to them when their request is granted with ease. We have laid up for ourselves a share of that forbearance we borrowed, and something of the manners we acquired in the years now past — amid straitened means and hard demands. We bore that for the sake of its virtue, and we seek its aid against the disasters of affairs and the accidents of the ages. We cannot let it go to waste. This is the very hour of our need for it, the hour to put it to use in what has befallen us in this matter that has arisen among our brothers. There is no sense in leaving them and what they hold without laying it open with them and debating it — with the forbearance of the capable and the understanding of seekers — free of any doubt in what we ourselves hold, and free of any charge against these people that they have turned from the truth in heedlessness, for they stand nobler than that in our eyes, or that they have strayed into error, for such error is beneath them. Falsehood has no eminence for whose sake the plain truth should be abandoned. But reflect with me on the affair of these people, for it cannot escape one of three states. Either the people hold to what we already know of religion, and this new thing among them is only an increase in manners, hadiths, and poetry — and people''s speech is much; or the people have been granted an increase in what they hold of the religion, and they have delighted in it, and:</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">وَالْعِلْمُ ضَالَّةُ كُلِّ مُؤْمِنٍ</span></p></blockquote>
<p>Knowledge is the lost property of every believer, and an increase in knowledge is better than a loss of it; or the people have been given a guidance other than what they had — from the prophethood of a prophet who came to them with it and called them to it, and they followed it upon a clear proof. None of this can be ruled out of the command of Allah, nor will creation reach the limit of Allah''s decree concerning them and His will for them, however hard they strive, for:</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">وَإِنَّ اللَّهَ كُلَّ يَوْمٍ هُوَ فِي شَأْنٍ</span></p></blockquote>
<p>And Allah, every day, is upon some matter.&quot;</p>
<p>They said: &quot;Abu Malik, we came to you with hearts full of rage against these people — ready to call them unbelievers and refute their view, to the point that we held their blood and their property lawful. But we have found our hearts humbled by your words, and by the way you have stood by their argument and defended them.&quot;</p>
<p>Abu Malik said: &quot;This argument of mine is not for their sake; it is for the truth, that I might not betray it while it is unseen. I have stood by the truth''s argument on its behalf when the one who would argue for it is absent. Nor is it a defense of them; rather I have defended myself and you against speaking falsehood, and against hurling ourselves blindly into what we have not encompassed in knowledge. Otherwise we would be, in that, like the tyrants of the nations gone before, when their doctrines pleased them in their own forbearance and they rejoiced in the knowledge they had — until they supposed they had encompassed all that Allah had commanded, taught, and willed of that for His creation. So they said Allah would send no messengers after their messengers, and they never imagined that beyond the knowledge they had reached lay any doctrine at all. They passed judgment upon Allah that He should cut off His argument from His creation and His deputies in His earth. Then they made the knowledge of Allah in His servants, and that for which He had sent His prophets and messengers, the measure of their own minds, so that whatever ran past it was, in their view, error. By that opinion they went astray and led many astray. By their own ruling they made lawful what Allah had forbidden, and by their own view they killed the prophets of Allah. I seek refuge for you in Allah, that you should follow the whims of a people who went astray before you. For men of intellect can be bent by whim toward any meaning, and lured away from every path — save the path of religion, for it is the more forgiving in the seeking, and its merit is not hidden.&quot;</p>
<p>They said: &quot;Abu Malik, we do not oppose your command, and your counsel to us is not lost on us. We would not obey you at the outset of our affair only to differ with you at its close. You have pointed to the course and hinted at the demand. If you see fit, take us to these people, that we may lay open their doctrine with them and examine it. If it is right guidance, we will follow it; and if it is error, we will shun it.&quot;</p>
<p>Abu Malik said: &quot;That is doubt on your part in what you hold, and the doubter knows neither his own right nor another''s falsehood.&quot;</p>
<p>They said: &quot;Then we hold firm to our truth and give the lie to whatever differs from it, whatever it may be.&quot;</p>
<p>Abu Malik said: &quot;That is not how the meaning is sought, nor is guidance found by giving the lie.&quot;</p>
<p>They said: &quot;How, then, is the demand to be made, if we neither give the lie to falsehood nor affirm the truth?&quot;</p>
<p>Abu Malik said: &quot;If you already know the truth and its acceptance, and know falsehood and how to give it the lie, then you are not among the seekers at all; you are among the learned in prophethood and guidance, who judge over the people of the world by revelation.&quot;</p>
<p>They said: &quot;Then we are content with the truth we hold, and we do not doubt it, and we excuse ourselves from the burden of the demand.&quot;</p>
<p>Abu Malik said: &quot;Are you not troubled that they should have merit over you in one respect, when by this you would grant them merit over you in many? Would you be content to stand, through need, in the stations of the seekers, only to stand, through ignorance, in the stations of those who sit idle?&quot;</p>
<p>They said: &quot;How has that come about in us, and what merit have they over us?&quot;</p>
<p>Abu Malik said: &quot;Their merit over you lies in knowing what you know, and in an increase of what you do not know. This is a matter that has come upon a people: if you do not seek them out over it, they will seek you out for it; and if you will not listen to it, they will strive against you in it — and so they will win the merit over you by precedence, by demand, and by striving. As for sitting back from the demand, that is ignorance through and through, and negligence, and a fault upon the learned man until he teaches, and upon the ignorant man until he learns.&quot;</p>
<p>They said, &quot;Abu Malik, you have met us with argument at every turn, and every word of yours is sound. So open for us, from your own judgment, a door we can act through.&quot;</p>
<p>Abu Malik said, &quot;To be pleased with one''s own opinion is a kind of blindness, and to neglect the search is a kind of error. There is no fault in searching itself for those who seek, but the seeker must first know the doorways of the search, so that he seeks the truth by knowing how to seek it. Whoever seeks the truth without knowing how is the quickest of all to call it a lie, because falsehood announces itself early by its showiness and by how readily it agrees with what people already think, while the truth announces itself early by the hardship it brings and by how it cuts against a man''s desires. And no one lets go of his own desire and bears the first onset of hardship patiently except the man whose heart is sound.&quot;</p>
<p>They said, &quot;Now a door has opened for us, one in which you point us toward the knowledge of the search. So make plain to us what that knowledge is, and what the sound heart is.&quot;</p>
<p>Abu Malik said, &quot;The knowledge of the search is that you know yourself to be in need. And the man in need seeks what he needs with the humility of one who wants something, standing before the very thing he asks for. As for the sound heart, it is a heart that does not keep denying whatever comes to it, no matter what it is, until the truth becomes the thing that makes itself plain and shows its own worth, and falsehood becomes the thing that lays bare its own disgrace. Then the heart tells falsehood apart by its own intelligence, and takes the truth in by its own readiness to receive it.&quot;</p>
<p>They said, &quot;We have been told that whoever stands at this station — neither affirming the truth nor rejecting falsehood — is a man ignorant in his conduct, since he neither knows the truth well enough to follow it nor knows falsehood well enough to avoid it.&quot;</p>
<p>Abu Malik said, &quot;What you have reported, you have believed. But has such a man not, by your own reckoning, passed out of the class of liars and entered the class of the ignorant?&quot;</p>
<p>They said, &quot;Yes. To our minds he is ignorant, not a liar.&quot;</p>
<p>Abu Malik said, &quot;The ignorant man is the one more to be hoped for where good is concerned, and where the seeking of good is concerned. He seeks knowledge for his own sake; and if he does not, the learned seek it out for him — for ignorance is the state every creature is born into, and there is no shame in it for a man who seeks knowledge on account of that very ignorance. Lying, on the other hand, is the worst of wares to trade in. The liar takes no guidance from his own lying, and he is never believed, even in what is recorded against him.&quot;</p>
<p>They said, &quot;You have made us certain of it. We now know the flaw in lying, and so we will never again deny a thing until we know it for what it truly is. And you have shown us the doorway of the request — the reverence born of need for the thing sought. Now, is this reverence and humility toward the thing sought to be shown after it has made its rightness plain, or before it has spoken at all?&quot;</p>
<p>Abu Malik said, &quot;Only before it speaks, so that by your reverence you may draw its answer out of it.&quot;</p>
<p>They said, &quot;Then suppose we revere the thing sought until what it holds within is made clear, and its answer turns out to be error — what becomes of that reverence? Has it not been spent for nothing?&quot;</p>
<p>Abu Malik said, &quot;No. Rather it returns as reverence toward God and as lowliness before His command, and its reward is yours even if the one before whom you humbled yourself did not deserve it. For the seeker has paid the debt owed to the request, though the debt owed to the truth was never paid to him. His case in this is like the case of a man standing before some king to ask for a gift: in his asking, nothing is open to him but reverence, soft words, and the pressing of his plea. If the king gives him some part of what he asked, the king has paid the debt of the favor, and there is a reward for him in what he gave. And if he gives nothing at all, the petitioner has still paid the debt of the asking through the gentleness of his request, and it is the withholding that has bound the one who refused. So it is with the seeker of knowledge: it falls to him to begin with reverence, humility, and patience under trial until he has paid the debt of the request; and after that, time will bring him whatever it brings.&quot;</p>
<p>They said, &quot;This is the plain and open truth. Will you give us leave to go out to the people upon what you have counseled us, and to overstep nothing of what you have commanded?&quot;</p>
<p>Abu Malik said, &quot;I would never counsel you to a thing and then be stingy with my own self in it. Were it not that I feared the fault of turning you back from the path of God, I would have counseled you to hold back while I went on ahead of you to the good — claiming that honor for myself and preferring my own soul above every other. But we go together, and I hearten you with my own company, as an honor to you and in thanks for the good you have singled me out to share.&quot;</p>
<p>They said, &quot;It is as though you had been waiting for this very affair before this day came.&quot;</p>
<p>He said, &quot;For this thing in particular, no. But I have never ceased to await relief from God from every side, hoping for good along every road, turning my ear toward every man who speaks and seeking some increase from his words, whether he be in the right or in the wrong.&quot; They said, &quot;That a man might gain increase from the words of one in the right, we grant you. But how do you hope for increase from the words of one in the wrong?&quot;</p>
<p>Abu Malik said, &quot;Truth laid upon truth is light; and to know falsehood for what it is, from the mouth of the man in the wrong, is an increase in certainty. And the more certainty grows, the more the light of the heart grows with it. No one is saved in the sight of God but the people of certainty. I am rising now to go to the people. If you are resolved to rise with me, then look to yourselves: whoever knows of a sin in himself, let him repent to God; whoever carries a debt, let him render it to the one it is owed. Wash yourselves clean of every defilement, put on for the request the purest garments of resolve, and bring to the thing sought the intention of a man in need — for I myself am doing just this. Our going out is a going out to God. If He finds truthfulness in us, He will grant us success in reaching His truth; and if He finds in us mockery of the religion, He will turn us away from His signs by the smallest touch of abasement, vindicating His friend against those who mock.&quot;</p>
<p>They said, &quot;Yes. We will do what you have commanded — within three days.&quot;</p>
<p>He said, &quot;No.&quot;</p>
<p>They said, &quot;Within two days, then?&quot;</p>
<p>He said, &quot;No — only within this one day of ours. If you do it, well and good; and if not, then I am going on.&quot;</p>
<p>They said, &quot;Then we repent to God from every sin, and we render every debt, and we do what you have commanded. There is no strength save in God.&quot;</p>
<p>So they did this that very day, and they all went out together until they came to the gate of al-Bakhtari. When they had greeted him and were seated, Abu Malik said to al-Bakhtari, &quot;Abu Salih (<span class="ar-inline" dir="rtl" lang="ar">أَبَا صَالِح</span>, father of Salih), how is your son Salih, and where is he?&quot;</p>
<p>Al-Bakhtari said, &quot;Salih today is my father, and I am the son of Salih; and Salih is with his Lord.&quot; Abu Malik, supposing that Salih had died — for his father had said he was with his Lord — said,</p>
<blockquote class="quran"><p class="ar" dir="rtl" lang="ar"><span class="ar-inline" dir="rtl" lang="ar">إِنَّا لِلَّهِ وَإِنَّآ إِلَيْهِ رَجِعُونَ</span></p></blockquote>
<p>&quot;To God we belong, and to Him we return. Has Salih died?&quot;</p>
<p>Al-Bakhtari said, &quot;Salih has not died and never will. He endures as long as time itself endures.&quot;</p>
<p>Abu Malik said, &quot;Here are three matters whose meanings have been turned upside down: the son has become the father; the Lord is present here upon the earth, and this Lord has a servant through whom one is brought to Him; and a thing created to perish has become everlasting. Alas for seekers, at the tangle of such speech! And behind all this, I suspect, lies a further wonder still.&quot;</p>
<p>Al-Bakhtari said, &quot;Abu Malik, come to your need, and be steady in your asking, for you are only at the beginning of the trial.&quot;</p>
<p>Abu Malik said, &quot;You have spoken truly. The beginning of the truth is a trial. My need is a meeting with the righteous servant.&quot;</p>
<p>Al-Bakhtari said, &quot;There is no way to that. But perhaps you mean my son, Salih?&quot;</p>
<p>He said, &quot;Yes.&quot;</p>
<p>He said, &quot;That is by his leave.&quot;</p>
<p>So the old man rose in haste and went in to his son Salih, and told him of Abu Malik and his companions, and he rejoiced at the news, for he knew the excellence of their minds. He said, &quot;O God, open for Your servants the hearing of their hearts, guide them by Your mercy to the proofs of what is sought, and widen our breasts with the light of Your hidden light.&quot; Then he passed his hand over his face, cleared the sitting-place for them, and gave word to his father to bring them in.</p>
<p>When they had come in to him, greeted him, and taken their seats — Abu Malik and those below him settling into their places in order of rank — Salih drew Abu Malik near and seated him close beside himself. The first thing Salih said was, &quot;Abu Malik, you have honored us with your visit and outrun us to the good by your generosity; yet the greater right was ours, that we should have visited you, to keep faith with your affection and to render the long-standing debt owed to you.&quot;</p>
<p>Abu Malik said, &quot;When were you ever wanting in excellence, Abu al-Khair (<span class="ar-inline" dir="rtl" lang="ar">أَبَا الْخَيْرِ</span>, father of the good)? You were forbearing with us when we were small, and generous to us once we were grown, and you became among us one who calls to the good and warns against its opposite. Your root is wholesome, your branch stands high, your work is pure — so joy be to you.&quot;</p>
<p>Salih said to him, &quot;Have you come to me as one who suspects, O Kab al-Ahbar, or as one who merely imitates? Where is that complete mind and fine forbearance I once knew in you?&quot;</p>
<p>Abu Malik said to him, &quot;Your standing is too high for suspicion, and the religion is too high for mere imitation.&quot;</p>
<p>Salih said to him, &quot;Then how do you call me a warner, when the warner is a prophet, and the prophet is a proof set by God between Himself and His creation — a proof for them and against them alike? How can one be a proof for you who is not also a proof against you?&quot;</p>
<p>Abu Malik said, &quot;You have spoken truly; this is its due. We do not go about this on the strength of easy words; but we began with you by way of what is fairer. I judged truthfulness the fitter thing for a man who has set himself up as a veil for the religion and a champion for the truth, and who has thrown its doors open to those who seek. We have come to know the excellence of the request, and so we sought you out and set our hope upon you as the one sought. Come, then, to our need.&quot;</p>
<p>Salih said, &quot;Abu Malik, is not the man whose excellence you have come to know also a man whose right has become binding upon you?&quot;</p>
<p>He said, &quot;Yes, it is binding.&quot;</p>
<p>He said, &quot;Then when you came to know the excellence of the request, did you also come to know its due?&quot;</p>
<p>He said, &quot;And what is its due?&quot;</p>
<p>Salih said to him, &quot;To know its several faces, and then to seek out from among them the one in which the truth becomes binding upon you.&quot;</p>
<p>Abu Malik said, &quot;And what are its faces, and how many faces has it?&quot;</p>
<p>Salih said to him, &quot;The request has three faces: a seeker who knows, a seeker who is coming to know, and a seeker who is only beginning to acquaint himself. Which of the three are you?&quot;</p>
<p>Abu Malik said, &quot;I have need to know all three. How could I lay claim to a station I do not even know?&quot;</p>
<p>Salih said to him, &quot;Then how did you lay claim to being a seeker at all, when you do not know the faces of the request?&quot;</p>
<p>Abu Malik said, &quot;I did not know them; so make them plain to me.&quot;</p>
<p>Salih said, &quot;Wealth is the treasure of the people of this world, and knowledge is the treasure of the people of the Hereafter. The seeking of wealth is of three kinds: a seeker who seeks what he already owns; a seeker who seeks a thing owed to him and due at a fixed term; and a seeker who seeks the gift of alms. In just the same way, the seeking of the religion and of the treasures of the Hereafter has three faces. The first is a seeker who knows, and he is the godly scholar, who seeks out the dead in their ignorance to bring them back to life with his knowledge. The second is a seeker who is coming to know, and he is the learner who has come to know some of the degrees of knowledge and now seeks its farthest reach and its end. The third is a seeker who is beginning to acquaint himself, and he is the ignorant man whom his own ignorance makes known, who knows nothing beyond the fact that he knows himself to be in need; and so he seeks out the scholars in order to learn. These are the three faces, and these the descriptions of the seekers.&quot;</p>
<p>Abu Malik said, &quot;Yes. These are the faces of seeking, in religion and in the world alike. And I am the seeker who is only beginning to acquaint himself — the one who knows nothing, yet has come to know that he is in need. So teach me.&quot;</p>
<p>He said, &quot;Did you come to know it, or did you come to know it by sight?&quot;</p>
<p>Abu Malik said, &quot;And what is the difference between the two?&quot;</p>
<p>Salih said, &quot;Knowledge is report; direct knowing is to see a thing with one''s own eyes.&quot;</p>
<p>Abu Malik said, &quot;This too is among the things a man has need to know.&quot;</p>
<p>Salih said, &quot;Report is the case of an ignorant man who does not know that he is ignorant until he meets a scholar, and the scholar tells him of his ignorance. Then, on the scholar''s word, he knows that he is an ignorant man in need of knowledge — and so his knowledge of his own ignorance reached him as report. Knowing one''s need and ignorance by direct sight is otherwise: it is the man who has come to see within his own mind that he is asked about a thing and does not know how its answer runs. His breast is straitened by the ignorance, and he hopes for no relief except through knowing the very thing of which he was ignorant — and so his ignorance became a knowing he arrived at through his own mind. Ignorance is want, and want is a straitness, and straitness is a severe need that drives creatures to seek out room to breathe; and that room is the room of knowledge, for knowledge is wide and spacious. By this I have come to know that you are in need.&quot;</p>
<p>Abu Malik said, &quot;I find within myself everything you have described. I have come to know that I am in need — in severe want. Relieve my want, then, by your excellence.&quot;</p>
<p>Salih said, &quot;I see you rushing to ask before you have made certain.&quot;</p>
<p>Abu Malik said, &quot;Want hurried me on with its straitness, so I hurried; and I came to know how good it is to have room to breathe, so I went seeking it.&quot;</p>
<p>Salih said to him, &quot;If want has hurried you, and you have come to know the excellence of that breadth, then how do you stand as to knowing the one you seek?&quot;</p>
<p>Abu Malik said, &quot;Your excellence was made plain to me, so I made my way to you; the meaning was hinted at, so I sought you out.&quot;</p>
<p>Salih said to him, &quot;And from where was it made plain to you that it is I, and not you, who is known for breadth, that you should seek me? From where did you learn that I am the one sought, that you should come to me? No scholar versed in prophecy pointed you toward me, that you might learn from him; nor have you seen in me the confirmations the proofs supply, that you might know. Do you not see that you rise to the asking on nothing better than the ease of imitation, and so wrong wisdom and wrong yourself — like a man who measures with the underside of the measure? If he does not level it off, he wrongs the one he owes; and if he does level it off, he wrongs himself. So it is with one who takes his knowledge by imitation: if he acts upon it, he earns no thanks; and if he abandons it, it is called unbelief. And you, in my judgment, are of too fine a mind for that.&quot;</p>
<p>Abu Malik said, &quot;I know indeed that this is so. But I had hoped that the truth is a thing that establishes itself, and that I might spare you the trouble of making certain; for disputation breeds contention, and contention breeds rancor, since each opponent is out to gain the upper hand over the other. And when was the truth ever won by a man who has thrown himself into the defense of what is false?&quot;</p>
<p>Salih said to him, &quot;Excellent, what you have said. The truth does establish itself, by its own excellence and honor; and when quarreling grows large, it turns the heart away from what is worthier than the quarrel. Yet there is no abandoning the way the scholars have laid down, for they have said: no seed thrives in earth that has not first been sweetened for it, and no knowledge grows in hearts that argument has not first purified for it.&quot;</p>
<p>Abu Malik said, &quot;Then bring forward whatever arguments you will. For the speech of wisdom is like a jewel: turn it, and its light shines out; leave it lying, and its excellence is still not hidden.&quot;</p>
<p>Salih said to him, &quot;You have spoken truly — but only where no counterfeit of coated glass is set beside the jewel; there, indeed, the jewel is not hidden. Yet when claims grow many, and the tyrants of the world contend over the religion until they dress it in what is not itself and coat it with the counterfeit before those who seek it, then it becomes binding on the seeker to put the jewel to the test, so that its excellence may be made plain and the coated thing, along with its people, laid bare.&quot;</p>
<p>Abu Malik said, &quot;You have dealt fairly and given the truth its due. As for the counterfeit these people trade in, we came to know it and its flaws, and so we rejected it and held fast to this doctrine by which we came to recognize one another, and we said: here is the sound jewel of speech. We stood by it, and you agreed with us upon it, and together we all took hold of its rope. So if you have found in its substance a meaning finer than it — well, by my life, one jewel can be finer than another. Show me, then, the excellence of your jewel, by a test through which its worth is known. As for our jewel, we have come to know it and made it known; so tell us what you make of it.&quot;</p>
<p>Salih said to him, &quot;As for your jewel, it was honored among us and ranked with the sound jewel, until we submitted it to the jewelers and the men of the mines. They pronounced it false and would not take it from us as a jewel, and said: this is coated glass. They showed us its flaws, and it fell out of the class of the jewel. For a jewel is exalted only by its preciousness, by the recognition the people of insight give its excellence, and by their competing for it, until its price climbs to every height. And once the jewelers have cast it down, who is left to prize it but them — who will take it thereafter save the people of delusion, who neither sell nor buy? So too with knowledge: it is not knowledge until it has been submitted to those who possess the knowledge of heaven. If they accept it, it is sound knowledge; if they do not, it is idle talk — and idle talk has no place in wisdom, nor do the wise accept it.&quot;</p>
<p>Abu Malik said, &quot;And who are these who possess the knowledge of heaven, now that the prophets and the messengers are gone? For we know of none such in this age of ours, and the people have had no dealings with their like since revelation by the Books was cut off; the nations follow nothing now but the reports handed down. What, then, is your word on this?&quot;</p>
<p>Salih answered him, &quot;Any religion held to by way of the handed-down reports alone is not to be called a religion, for religion is one, upright, God''s by His own right, and admits no disagreement within it. The reports, as you already know, are full of disagreement, each one giving the other the lie — and the religion of God is far too precious for that.&quot;</p>
<p>Abu Malik said, &quot;But when they differ over a report, they fall back on the Books. Whatever agrees with the Books they accept; whatever contradicts them they call a lie.&quot;</p>
<p>Salih said to him, &quot;And what stands in the Books only in general terms — who will make it particular for them? And what stands there in detail — who will trace it back to its principle for them? Which of them is to be trusted over what God has made lawful and what He has forbidden? I heard you on the day of the dispute, when a man in distress came to you and said, O Abu Malik, I swore an oath of divorce and then broke it. You said to him, Some people hold that she has left you and is not lawful to you until she marries another husband; and some hold that she is still your wife and is not made forbidden to you by a single pronouncement. The man said to you, Then which of the two am I to act upon? You said to him, Act upon whichever of the two you please. So he rose from beside you not knowing whether he was going home to what is lawful or to what is forbidden. Is this how a ruling is given in the religion of God? Is this how God''s lawful and His forbidden are made known?&quot;</p>
<p>Abu Malik said, &quot;The sacred law of my age has been ruined, suspended, and thrown into disorder, and we hold to nothing now but the name of religion. What, then, is the state of religion in your view?&quot;</p>
<p>Salih said to him, &quot;And what is religion, O Abu Malik?&quot;</p>
<p>He said, &quot;Command and prohibition; the lawful and the forbidden; the sunnahs and the obligations.&quot;</p>
<p>Salih said to him, &quot;And what, in your view, is the sacred law, if not this?&quot;</p>
<p>Abu Malik said, &quot;I know of nothing beyond what I have just described to you.&quot;</p>
<p>Salih said to him, &quot;Then you have set religion and the sacred law together on a single ground?&quot;</p>
<p>He said, &quot;Yes.&quot;</p>
<p>Salih said to him, &quot;Then religion has been thrown into disorder by the suspension of the law, and ruined by its ruin. What is left to you?&quot;</p>
<p>Abu Malik held back from answering for a while, his head bowed, turning over the matter of his religion. Then he raised his head and said, &quot;I do not see that anything is left to me. So what is religion in your view?&quot;</p>
<p>Salih said to him, &quot;Religion, in my view, has its veil drawn fast against the corrupters and its doors thrown open to the seekers. Noble is the one who reaches it first, and good attends the one who seeks it; through it works are honored, and through its justice the sacred laws come into flower. It is a bond joined from heaven to earth, unbroken and unsevered — the handhold of those who take hold, the rope of those who cling fast, the ark of tranquility, the ship of salvation, the light of life: noble in its content, safeguarded in its sciences, marked out in its jewels, its excellence hidden from none who look upon it.&quot;</p>
<p>Abu Malik said, &quot;If God has a religion by which He will judge on the Day — one He is pleased with, one for which He rewards and punishes — then in that sense it exists. But now that it has been lost, its description has become clearer to me than the thing described. So how is it described?&quot;</p>
<p>Salih said to him, &quot;The good comes only from the good, O Abu Malik. Set your light in the lamp-niche of your intellect and grasp what is meant for you. The claims of what is decreed have pulled at you, the robes of arrogance have made you forget yourself, and you have taken upon your shoulders what none but you can bear — together with the affairs of these people who follow you in good faith, who have listened to your word, accepted your guidance, and trusted your judgment. It is your duty to shield yourself and them from a fire you cannot escape passing over; so seek the way to be saved from it. You are the most favored of them in God''s grace, and the most bound to render Him thanks, for I have known you to recognize the good and to hope for its reward. As for what you asked — the establishing of that to which I have called you — it is my duty to prove it to you by whatever avenues you wish.&quot;</p>
<p>Abu Malik said, &quot;Everything you have said up to this point is proven and true. As for the reports of the common people, religion is not made sound by them, and they are not fit for it. There remains for us only the knowledge of that to which you call us.&quot;</p>
<p>Salih said to him, &quot;I call you to the justice of God and to His oneness.&quot;</p>
<p>Abu Malik said, &quot;Excellent, that to which you call. Indeed, this very saying is what we hold, and we know its excellence above every other doctrine.&quot;</p>
<p>Salih said to him, &quot;It is not where your fancy has run off to, O Abu Malik. The doctrine you mean is a describing of justice with no knowledge of the One so described, and a wandering among the names of God with no knowledge of His oneness. What I call you to is the knowledge of God''s justice and the landmarks of His oneness. If you wish, I will halt you before the flaw in that saying at any point you please.&quot;</p>
<p>Abu Malik said, &quot;If the doctrine of the people of justice is flawed, and their affirming of oneness a wandering, then there is no firm truth left upon the earth — unless the meaning be something other than all the doctrines. Show us, then, where the flaw in justice and oneness lies, and where it comes from.&quot;</p>
<p>Salih said to him, &quot;Justice and oneness are among the noblest of all doctrines. Oneness is too great to be corrupted, for oneness has no opposite; and justice is not corrupted, for it is the judgment between God and His creation. But the doctrines are all corrupted by the way men have corrupted the saying of justice and the rest — for it is a claim by which no statement is proved, and they do not encompass the knowledge of what they have said until they defer to the command of God. So take up whichever of the two you wish, defend it, and make it your own, until I strip it from you by the proof of the truth.&quot;</p>
<p>Abu Malik said, &quot;I would not defend a saying I do not hold, nor one whose author has asked this of me; I have not set myself up as agent for his saying, nor am I a keeper over the authors of the doctrines. Before you I defend only my own saying. I say that God is One, that nothing is like Him (<span class="ar-inline" dir="rtl" lang="ar">لَيْسَ كَمِثْلِهِۦ شَىْءٌۭ</span>), just in His ruling, who lays upon His servants no burden they have no strength to bear. He commanded them and forbade them, yet He did not command by compulsion nor forbid by force; rather His command is a granting of choice, and His prohibition a warning — so that the obedient did not obey under coercion, and the disobedient did not disobey as men overpowered. This is my meaning, and this is what I hold.&quot;</p>
<p>Salih said to him: &quot;Did I not tell you that this doctrine is among the noblest? Yet names and attributes are of no use unless their meaning is present. Say, for instance, that fire is hot: you have spoken the truth, but the truth does you no good, because the words fire is hot are only a name and an attribute. Uttering them cooks no food and lights no darkness — that is done by the meaning, which is that fire actually exists. If names and attributes could take the place of the meanings themselves within things, then the word fire would burn your tongue and the word food would fill you.&quot;</p>
<p>Abu Malik said: &quot;As for what you say about these things, you have spoken the truth, for their names and attributes are of no use unless their meaning is present. So show me that when I speak of justice and of oneness, these too are names and attributes that call for the knowledge of a named and described thing.&quot;</p>
<p>Salih said to him: &quot;Take your saying that God is one. The word one (<span class="ar-inline" dir="rtl" lang="ar">وَاحِد</span>) is four letters, and we see two of them joined and two of them standing apart. Which of them is the one? Or are all of them together the one? And your saying Allah is four letters: which of them is Allah? Or are all of them together Allah? Or are they signs that point to God? Or do you say something else?&quot;</p>
<p>Abu Malik lowered his head for a while, then said: &quot;I can find no way out of this except to say that they are signs pointing to God.&quot;</p>
<p>Salih said to him: &quot;Which of them points to God? And how do they point to Him — by standing apart or by being joined? Or do some stand alone while others are joined, as in your saying Allah, where the alif (<span class="ar-inline" dir="rtl" lang="ar">الْأَلِف</span>) stands alone and the three letters are connected? Which of them points to God: the one standing alone, or these joined together?&quot;</p>
<p>Abu Malik said: &quot;I do not know what to tell you about this. Lead us on to another door.&quot;</p>
<p>Salih said to him: &quot;Then the door to the knowledge of oneness has been shut in your face, O Abu Malik, by whoever spoke to you in this way.&quot;</p>
<p>He said: &quot;Yes.&quot;</p>
<p>Salih said to him: &quot;Then let me ask you about your knowledge of God. Where does it come from, and from whom did you receive it? Was it from an attribute that pointed you to One who is described?&quot;</p>
<p>He said: &quot;No.&quot;</p>
<p>Salih said: &quot;Then from a name that points to a named one?&quot; He said: &quot;Yes.&quot; Salih said: &quot;And what is the name that pointed you to Him?&quot;</p>
<p>He said: &quot;Allah.&quot;</p>
<p>Salih said: &quot;Is Allah the name, or the named?&quot;</p>
<p>He said: &quot;The named.&quot;</p>
<p>Salih said: &quot;Then what is the name?&quot;</p>
<p>He said: &quot;Allah.&quot;</p>
<p>Salih said: &quot;So Allah is a name for Allah.&quot;</p>
<p>He said: &quot;Yes.&quot;</p>
<p>Salih said: &quot;Then what is the difference between the name and the named? And which of the two do you worship — one of them, or both?&quot;</p>
<p>Abu Malik was at a loss for a while, turning his answer over in his mind, and then said: &quot;I can find no way through this except to say that I have considered all the crafts, and every craft has its craftsman; and from this I judged that this mighty creation has a Creator who resembles nothing of what He has created, just as craftsmen do not resemble the things they make.&quot;</p>
<p>Salih said to him: &quot;O Abu Malik, you have carried us away from the first meaning. The narrowness you feel in the meaning of oneness has driven you to seek Him by analogy and to invent likenesses for Him, and God is far too exalted for that. Every made thing is made from some thing, yet God did not create things out of anything that existed before them. These craftsmen you speak of, you know only because you watched some of them with your own eyes, how each one fashions his work; and so you passed judgment upon a making whose maker was hidden from you, reasoning by analogy from the like of it that you had seen among the craftsmen you have watched and known. But when God created, He did not make you a witness to the creation of what He made, nor did He have any like who makes as He makes; and yet you have taken the like that is present as a witness to the like that is absent. I have never known you, O Abu Malik, to be content with analogy in your religion; how then are you content to seek the knowledge of your Lord by measurement? Your saying, nothing is like Him (<span class="ar-inline" dir="rtl" lang="ar">لَيْسَ كَمِثْلِهِۦ شَىْءٌۭ</span>), proves out of your own mouth that He has a likeness and that nothing is like that likeness. Had you meant oneness, you would have said, He is not like anything (<span class="ar-inline" dir="rtl" lang="ar">لَيْسَ كَهُوَ شَيْءٌ</span>), and you would not have said, nothing is like Him (<span class="ar-inline" dir="rtl" lang="ar">لَيْسَ كَمِثْلِهِۦ شَىْءٌۭ</span>). Glory be to the One whom the reach of lofty resolves cannot seize by thought, and whom the straining of the pointing hand cannot attain by perception; rather He is exalted far above the description of those who are charged with duty. O Abu Malik, had you turned this quest toward one of His servants, or toward a king among His angels, you would have failed to grasp what might be said of him and how he was created — how then the One who created him? The lights of the people of the earth fall short of grasping the light of the sun, and the sun is but one of the lights of this world; so how shall the one who falls short of grasping a servant of His grasp the Creator? Say what seems right to you.&quot;</p>
<p>Abu Malik bowed long to the ground in his bewilderment, finding no path to speech.</p>
<p>Salih said to him: &quot;O Abu Malik, raise your head and say what has come to you of speech.&quot;</p>
<p>Abu Malik said: &quot;Speech is gone, and there is none left; the minds are bewildered before the answer, the fancies are struck dumb before thought, and the instrument is too weak to grasp with it anything but seeking and asking.&quot;</p>
<p>Salih said: &quot;O Abu Malik, One of such greatness — do the eyes grasp Him?&quot;</p>
<p>He said: &quot;No, He is higher than that.&quot;</p>
<p>Salih said: &quot;Is speech heard from Him?&quot;</p>
<p>He said: &quot;There is no speech except from a speaker, and a speaker is described by his speech, and God is too great for attributes.&quot;</p>
<p>Salih said to him: &quot;This Vast One of greatness, this High One of power — would He wrong His creation, charging them with what they cannot bear and commanding them with what they cannot grasp, and then punishing them if they fail to do it?&quot;</p>
<p>Abu Malik said: &quot;Whoever charges an obedient servant with what he has no strength to bear has charged him with disobedience, and to punish him for it is aggression, and God is far too exalted for that.&quot;</p>
<p>Salih said: &quot;O Abu Malik, One so far above wrongdoing and too great for aggression — would He be content that ignorance should keep His servants company?&quot;</p>
<p>Abu Malik said: &quot;Ignorance is an outright denial of thanksgiving and a persisting in disbelief, and God loves none of the disbelievers.&quot;</p>
<p>Salih said: &quot;Were they, then, created already knowing, aware of what is wanted of them?&quot;</p>
<p>He said: &quot;No, He created them ignorant, knowing nothing.&quot;</p>
<p>Salih said: &quot;Then how do they come to know what He wants, so that it becomes binding upon them to please Him and to guard against His wrath?&quot;</p>
<p>Abu Malik said: &quot;They learned this from God.&quot;</p>
<p>Salih said: &quot;If He is higher than sight can reach, wider than perception can grasp, and greater than the bounds of speech, then how does the one whom He commands and forbids come to know Him — so as to obey and not disobey, to give thanks and not deny — unless you grant that there are causes for this knowledge set between Him and His creation? Must there not be those who deliver His justice and bear witness to His witnessing, both for the servants and against them, whom He has chosen by His knowledge and singled out from all His creation, and made messengers to them and proofs against them, so that they stand as the just ones between Him and His servants, conveying His command and His prohibition, so that obedience to them is obedience to God and His good pleasure, and disobedience to them is His wrath and His punishment? For otherwise, how could the command reach creation from God?&quot;</p>
<p>Abu Malik said: &quot;This, to my mind, belongs to the foundations of justice. Once creation stands in need of God''s justice to be taught what He wants of them, and this comes by the hand of the righteous one He has appointed, then each shall thank his benefactor, be rewarded by Him as He wills, be reproached by Him, and be punished by Him if He wills.&quot;</p>
<p>Salih said to him: &quot;Is it permissible to rule with justice in any way other than this?&quot;</p>
<p>He said: &quot;It is permissible for none but God, and God is the wisest of judges.&quot;</p>
<p>Salih said: &quot;Would it be permissible in His judgment that He lay a charge upon some of His creation and guide them to it through one of His just ones, and then lay that very same charge upon others, yet not guide them to it through one of His just ones as He guided the first?&quot;</p>
<p>Abu Malik said: &quot;The judgment can only be one, because justice is one. Were the ruling divided into two meanings, one of the two would inevitably fall into wrong.&quot;</p>
<p>Salih said to him: &quot;Has it not been established for you, then, that the judgment of God is one, that there is no difference within it, and that His way is one, unaltered from messenger to messenger? Were it not for the succession of the messengers and the standing of the command and the prohibition, the Truth would have no growth and creation no meaning.&quot;</p>
<p>He said: &quot;Yes, this is the truth.&quot;</p>
<p>Salih said: &quot;And is not this succession of theirs, from God to His creation, appointed so that He may make obedience binding upon them and impose it as a duty, and so that He may set them as an authority between Himself and His creatures — to bear witness for those who obey them, and so accept them, and to bear witness against those who disobey them, and so turn away from them?&quot;</p>
<p>Abu Malik said: &quot;The judgment could not have been otherwise; else He would have belied His messengers and broken His promise, and God is far too generous for that. The affair of the messengers has made it plain that they are of His justice, and that the servants worship Him by obeying them. But tell me of the ranks of these just ones before God: are they equal, or do some of them hold a merit above others?&quot;</p>
<p>Salih said to him: &quot;How could they be equal in rank when they are bound to render obedience one to another? Were they equal in rank, none of them would obey another. Rather, by His justice He has preferred some of them above others, so that obedience may pass from the lesser to the greater, and from the greater to one greater still, until obedience and worship reach through them the utmost limit that God has willed.&quot;</p>
<p>Abu Malik said: &quot;And are the one who obeys the virtuous one among them and the virtuous one himself equal in reward?&quot;</p>
<p>He said: &quot;Yes; this belongs to the justice of God, which makes the due reward binding for every obedient servant, and one is not questioned about the rank of a virtuous one or a lesser one.&quot;</p>
<p>Abu Malik said: &quot;Can anyone resemble the virtuous ones?&quot;</p>
<p>He said: &quot;That cannot be, because they come from the Creator bearing the knowledge of the unseen in the Books He has sent down to them, and no one is able to bring the like of it except from God.&quot;</p>
<p>He said: &quot;Then can anyone imitate the lesser one among them, since no Book is sent down to him in which knowledge of the unseen is revealed?&quot;</p>
<p>He said: &quot;No one is able to lay claim to that station.&quot;</p>
<p>He said: &quot;And how is that, when they did not set forth the seven creations of the unseen as the virtuous one himself set them forth?&quot;</p>
<p>Salih said to him: &quot;If the virtuous one has set himself apart from others by the knowledge of the unseen in the revelation sent down, then the lesser one likewise has set himself apart from others by the knowledge of the unseen in the interpretation. Both its sending down and its interpretation are from God, and what is with God is attained only through inspiration.&quot;</p>
<p>Abu Malik said: &quot;And is the lesser one also inspired?&quot;</p>
<p>He said: &quot;Yes, and for that very reason obedience to him became obedience to God.&quot;</p>
<p>Abu Malik said: &quot;If you set him level with the virtuous one in obedience and in inspiration, why then do you call him the lesser one?&quot;</p>
<p>Salih said: &quot;Because of his obedience to the virtuous one and his need of him.&quot;</p>
<p>Abu Malik said: &quot;And what need has he of the creature, when the inspiration reaches him from the Creator?&quot;</p>
<p>Salih said to him: &quot;Even though the inspiration reaches him, it comes bearing the interpretation of the reports and the Books, and the remainder of what the virtuous ones have left behind — as it was revealed to Lot at the hands of Abraham, so that Abraham''s merit was made plain; and as it was revealed to Ishmael and to Isaac, so that the goodness, the blessings, and the merit accrued to Abraham. Thus the inspiration from God is joined to His just ones upon His earth, each according to the measure of his rank. In His justice, He does not will to cut off His command, His prohibition, and His worship from His servants after He has favored them with it; for then worship would be severed and ignorance made lawful.&quot;</p>
<p>Abu Malik said: &quot;The bearer of the revelation has shown his truthfulness by the knowledge of the unseen that is in his Book. By what, then, does the bearer of the interpretation show that the knowledge of the unseen is with him, so that the revelation bears witness for him and makes obedience to him uniquely binding, as it did for the bearer of the revelation?&quot;</p>
<p>Salih said to him: &quot;He comes in his interpretation with knowledge from heaven and a declaration from the highest assembly, and the Book bears witness to it.&quot;</p>
<p>Abu Malik said: &quot;Then I bear witness to what the Books have borne witness to: that every interpretation to which the revelation testifies is a revelation from God; and otherwise the Books and the messengers would all have to be belied, since their meaning is one.&quot;</p>
<p>Then he said to him: &quot;If some of them call others liars, then all of them must be counted liars; and if some of them confirm others, then all of them must be confirmed.&quot;</p>
<p>Abu Malik said to him: &quot;This is justice; by it truthfulness is known, and so is the merit of the one who confirms it. He has made obedience binding upon the possessors of firm resolve among the messengers, who are His just ones among His creation, and He charged them with delivering His message. If, then, obedience is made binding by prophethood, by revelation, and by interpretation, what of those who sit in their councils imitating them, yet are not of them? They have all agreed that after their prophet there is no prophet, that in their time there is no warner, that they themselves uphold the command of God and His religion, and that this saying of theirs leads to God''s reward or His punishment. Yet you say otherwise. How, then, could the scholars of this community have failed to look into this age?&quot;</p>
<p>Salih said to him: &quot;They have not left it entirely untouched, but they have not examined it with the kind of consideration that would set them right, nor has anyone spoken to them of it so that their minds might incline toward it; for it has been made to soak into their hearts that they are the worthiest of the command of God and His religion, and that there is no prophet after their prophet—just as the seducers of the bygone nations said before them. So every nation has claimed that there is no prophet after its own prophet.&quot;</p>
<p>Abu Malik said: &quot;And what was the beginning of that, and what did they intend by it?&quot;</p>
<p>Salih answered him: &quot;In every age it began with three men: a rebellious devil, a stubborn tyrant, and a dissembling jurist. By the saying they spread abroad, they meant to cut the traces of the prophets off from every mark of prophethood, and to turn prophethood itself into a dominion handed round among their own. They could not accomplish this until they had made the hearts of the nations drink in a single claim, pressed alike upon every nation: that God has sent no one better than your prophet, and that after him there is no prophet and no warner. So they whispered to them from a quarter they never perceived, and turned them from a direction they never knew. Each nation clung to its own prophet by denying whoever came after him, imagining that this drew it nearer to that prophet; and each nation branded every prophet who came after its own a liar. In this way the mention of prophethood and the traces of the prophets were cut off from all the nations together, so that they neither sought what they had lost nor would have believed had they sought it. Thus the seducing devils gained mastery over the misguided and led them astray; the tyrants gained the power to kill the prophets and killed them; and the doubt-sowers among the corrupt jurists preened themselves, and were destroyed and destroyed others. All of this was because the hearts of creation would not incline toward the prophets when they appeared, nor seek them out once they were gone. So deep did their despair of the prophets run that when the prophets called them plainly to the truth, they were called liars and were killed in the midst of the people, and no one felt any anger at it. Consider the nation of the Magi, clinging to its tyranny, worshipping its idols, keeping vigil over its fires, claiming that God will never send a messenger after their messenger. Consider the nation of the Torah, clinging to its scripture, bowed over its calf, standing by the bounds its prophets set, humbling itself before its Lord of judgment, claiming that God will never raise a messenger after Moses. Consider the nation of the Gospel, speaking in its parables, claiming that its prophet is its God, seeking nearness through its crosses, exalting its rabbis, saying that God will send no messenger after Jesus. And consider your own community: it has been led along the paths of those before it, and whoever went astray has drawn it into his straying; so it inherited the Book from other than its rightful people, walked with the religion along a way not its own, followed its great ones into error, obeyed its masters in misguidance, and its jurists abased themselves before the tyrants—until they set up for the people a religion other than the received practice, praying at other than its proper time and giving the alms otherwise than by its right. They stand banded together, patient with these masters, unwavering in their need of them, certain that they need no one else, saying that God will send no messenger and no warner after their Messenger. So you and those like you followed the word of the great multitude, won over by the sheer weight of consensus and the coercion of the rulers. You accepted it from them, dressed it in the elegance of your doctrines, gave it preference by the fineness of your phrasing, and raised upon it an argument from justice so tight that no argument can be raised against you. So you stood forth, propped up from above by the mighty for the sake of prestige, while those below followed you out of appetite, all of them supposing this was the truth. But if this community must indeed be believed in what it has decreed against God—that His proofs have been cut off from His creation by a single thread of consensus—then the nations of old are the worthier to be believed, for they hold three qualities by which the argument stands against you, and by which the truth is theirs rather than yours.&quot;</p>
<p>Abu Malik said: &quot;And what are those qualities in which their merit over us rises so high that their confirmation becomes binding if their saying is true, or their denial binding if their saying is crooked?&quot;</p>
<p>Salih answered him: &quot;Their saying is like yours, and yours is of the same stamp as theirs; your hearts have grown to resemble one another. And yet, in the argument, the merit is theirs over you. The first quality: they say they came to the religion of God before you, so theirs is the merit of the foremost. The second: the consensus, both theirs and yours, rests upon confirming what is with them, so theirs is the merit of the truthful. The third: your own testimony on their behalf, that their prophets are truthful and are the messengers of God—while not one of them has testified for your prophet, neither to prophethood nor to truthfulness. So the merit is theirs over you, by your own agreement with them together with their standing apart from you; for they say that whatever knowledge you possess is copied from theirs, and that theirs is the root of yours. This is their argument against you, clear in speech and plain in its justice. If, then, the ruling of creation is binding upon the Creator, the ruling of these people is the more binding still. But if it is the Creator who rules over His creation, abrogating what He wills and confirming what He wills, with none to overturn His ruling, then—by my life—the saying of all of them falls away, and the Creator stands foremost over creation and over the command, and every day He is engaged in some affair: <span class="ar-inline" dir="rtl" lang="ar">كُلَّ يَوْمٍ هُوَ فِى شَأْنٍۢ</span> Every day He is engaged in some affair.</p>
<p>His act is not to be denied, though He should send a warner every single day.&quot;</p>
<p>Abu Malik said: &quot;This community has folded itself into a far-reaching misguidance.&quot;</p>
<p>Salih answered him: &quot;Most of the ancients went astray before them; for they cast off the friends of God, stripped them of their right, and let their own fools take charge of their affair. They made lawful what God had forbidden, and did so deliberately, lest anything come to resemble prophethood and set the people longing for the prophets—and lest, when that longing came, they should hesitate to kill them. Instead they distracted the people with sovereignty and largesse, and drew them along in step with their own whims. In this they were helped by men outwardly known for truthfulness and piety, parading themselves before the people, until the very one who had commanded the community to the good turned it away from the good, and the very one who had forbidden it the wrong pointed it toward the wrong; and those loyal to the friends of God grew few, so that truth and falsehood came round in turns, like light and darkness in their alternation. Were it not for the remnants of God''s friends and His just ones in the earth, and the inspiration that comes to them, the little of truth would never prevail over the much of falsehood. For by what else would God set the foul apart from the good, if not by His just ones? And how would the argument of God reach the whole of creation, if not through them?&quot;</p>
<p>Abu Malik said: &quot;There is no way, and no escape, for the justice of God and His command, amid the throng of His adversaries, save through the just ones of God; and by them the argument from God to His creation is made sound.&quot;</p>
<p>Salih answered him: &quot;Then, once it is established that the company of the prophets of God are the just ones, is not each single one of them called just?&quot;</p>
<p>He said: &quot;Indeed, he is a just one, as it is said:</p>
<p class="ar-block"><span class="ar-inline" dir="rtl" lang="ar">شَهِدَ فُلَانٌ وَهُوَ عَدْلٌ مِنَ الْعُدُولِ</span></p>
<p>So-and-so testified, and he was one of the just.&quot;</p>
<p>Salih said to him: &quot;Then it is settled for you that the just one is the friend of God, and that this has now passed beyond your saying of mere attribution, so that he has become one who is himself described?&quot; He said: &quot;Yes, that holds as a saying.&quot;</p>
<p>Salih said to him: &quot;And whoever does not reach the one who is described—does the description profit him?&quot;</p>
<p>He said: &quot;The description does not profit him except by reaching the one who is described.&quot;</p>
<p>Salih said: &quot;Then whoever does not know the just one of Allah and His guardian—will his speech be just?&quot;</p>
<p>The narrator said: Abu Malik smiled and said: &quot;You have drawn me out of my own chapter on justice and monotheism, and nothing has drawn me out of it but the truth itself, in the clearest of arguments and the gentlest of speech. After this, what chapter is left to prove?&quot;</p>
<p>Salih said to him: &quot;From here, O Abu Malik, the counterfeit glass falls away from those who trade in the colors of jewels. They could never tell its worth; but set it before those who know the gem, and it is exposed, and those they deceived are exposed along with it.&quot;</p>
<p>Abu Malik said: &quot;I have believed, and I have acted upon it. But how are we to be kept safe from the nations that lead astray, and how are we to know the causes of Allah—or even one cause among them—when we never reach them in their own time, and in our own there is neither prophet nor messenger, as there was among the nations before us?&quot;</p>
<p>Salih answered him: &quot;Glory be to Allah, O Abu Malik. For a stretch of your life you have not ceased to speak of the justice of Allah, yet the moment we reasoned with you to establish it where it binds you, you turned back to speak of tyranny toward Allah, and to charge Him with injustice.&quot;</p>
<p>Abu Malik said: &quot;Allah forbid. I do not say that, for whoever says it has transgressed and forged a lie against Allah. From where have you bound me to it?&quot;</p>
<p>Salih said: &quot;From your own saying that the age of the prophets has passed you by, and that in this time of ours there is neither prophet nor messenger. Was the sending of those in the first ages a justice from Him toward His servants, or was it in vain?&quot;</p>
<p>He said: &quot;Allah forbid that it be anything but justice from Him.&quot;</p>
<p>Salih said: &quot;Then what has taken us out of that justice? Are we not His servants as they were, a creation like their creation, bound in service as they were bound? Has He then dealt unjustly with us after His justice toward them, so that we who come after are excused? Or has His giving run dry in this time of ours, so that we cling to the bounty granted to them, and He is content to receive that from us? Or has the way of Allah changed in our case after it stood firm for those before us, so that we should pronounce upon Allah that He has altered? Or is His justice a right owed to us and His judgment binding upon us, as His way was with those before us—since there is no altering the words of Allah, and none to reverse His judgment? And who deserves the name the just except the guardians of Allah? Who among all that Allah created is just, except the one Allah chose, so that by His command he became just? For this reason the ruling is called just, on account of the justness of the one who ruled by it; and the truth is called truthful, on account of the truthfulness of the one who spoke it.&quot;</p>
<p>Abu Malik said: &quot;It can be no otherwise, and it is not for us to say of Allah anything but the truth. Yet we followed our own speech to our own opinion, and ruled by the absence of the righteous from among us. If that is part of the ruling of Allah and His way with us—as was His way with those before us in the intervals between one messenger and the next, like the span that lay between the religion of Abraham and the time of Moses and the Torah, and the span that lay between the Torah and the time of Jesus and the Gospel—then we have stood upon that same footing, working through the interval, holding fast to the traditions and the way.&quot;</p>
<p>Salih answered him: &quot;The religion of Allah is too precious to Him for that. What interval was there after the religion of Abraham, when Allah sent after him Ishmael, Isaac, Jacob, Joseph, Jonah, and Shuayb, leading on to Moses? He inspired them to the doing of good deeds, to the call to the religion of Abraham, to the establishment of the prayer according to its way, and to the giving of the zakat according to its obligations, until the ruling of the Torah was sent down upon Moses. And what interval was there after the religion of Moses, between it and the Gospel, when Allah sent after Moses Joshua son of Nun, and Elias, Talut, David, Solomon, Zechariah, and John, leading on to Jesus? They upheld the ruling of the Torah, held fast to its religion, called to it, and recited its Psalms, until the ruling of the Gospel was sent down upon Jesus. So it was with those who passed before them and those who came after, and the many generations between whom none knows but Allah. Their messengers came to them with clear proofs, and to each Allah set forth parables, and each was called to the truth. Where, then, is this interval, and when was it? Allah Himself said, <span class="ar-inline" dir="rtl" lang="ar">عَلَى فَتْرَةٍ مِنَ الرُّسُل</span> — after an interval in the messengers — and so the verse affirmed the messengers and the interval alike. That interval was the season when the call rose again out of fear, so that men called to it in secret and in hiding. Why, then, should the earth ever be emptied of them? The earth is not left, for so much as the blink of an eye, without the just one of Allah upon it — whether present and manifest, or veiled away in fear.&quot;</p>
<p>Abu Malik said: &quot;This is a saying that cannot be refuted, a word set beyond all doubt. That Allah establishes His proof through the just and through the succession of messengers is settled and plain. But what is the meaning of their absence in this age of ours? What is its cause?&quot; Salih answered: &quot;And what was the cause of Moses''s absence, when he left the city of Pharaoh and passed out beyond it in fear and watchfulness, until he reached the land of Shuayb?&quot;</p>
<p>Abu Malik said: &quot;He was fleeing the people of Pharaoh and hiding himself from them, for he feared for his life once they had resolved to kill him.&quot;</p>
<p>Salih said: &quot;Have you heard, in this law of yours, of even one of the just — the just of Allah, the sons of His prophets — who was killed for the sake of the religion and bore it in patience?&quot;</p>
<p>Abu Malik said: &quot;Yes. A great many of them have been killed.&quot;</p>
<p>Salih said: &quot;Then which of the just of Allah would you have appear to you and to the people of your time? One who was killed, whom Allah raises up and sends back to you after his death? Or one who flees your midst, whom you would drive back into the very killing he escaped — when he has walked the way of Allah that His prophets and messengers walked, patient under fear and in hiding, until Allah judges between him and us, and He is the best of judges?&quot;</p>
<p>Abu Malik said: &quot;There is no blame on a man who walks the way of the righteous, fearing for his life and fleeing his people. The blame falls on the wicked nations and the helpers of the powers of darkness, who kill the prophets of Allah and His just ones and band together to do it.&quot; Salih said: &quot;Then what do you say of the one who kills the just of Allah and His proof? Where does he end, and where does the one who helped him end?&quot;</p>
<p>Abu Malik said: &quot;In the Fire — and with him, whoever blackened an ink for them or dipped a pen in their cause.&quot;</p>
<p>Salih said: &quot;And what do your jurists say of this?&quot;</p>
<p>Abu Malik said: &quot;They call down mercy upon the slain, yet they find no sin in the killer.&quot;</p>
<p>Salih said: &quot;And the man who obeys the killer of his own free will — is he not a partner with him in the blood of the slain?&quot;</p>
<p>Abu Malik said: &quot;Yes, by Allah. He is his partner, and worse than he.&quot;</p>
<p>Salih said: &quot;His partnership is plain, since he aids him. But how has he become worse than he?&quot;</p>
<p>Abu Malik said: &quot;Were it not for the rulings the jurists hand down, the kingship of the tyrants could never have stood upon the shoulders of fools.&quot;</p>
<p>Salih said: &quot;You have spoken the truth, Abu Malik. Have you, then, been content to make their kingship your home, their land your dwelling, their soldiers your neighbors, and their guardsmen your close companions — while you are their just one, judging for them by your knowledge and meeting your needs through their kingship? You called upon them in your petitions and thanked them for what you sought. You set the crown of your justice upon their tyranny, and they grew proud; you clothed their pride in the garment of the sacred law, and they went to excess; you lit up their falsehood by dimming your own truth. So the weak were led astray by your example, and so were the scholars who were like you, and they said, These are the jurists of the community; in them we have a pattern to follow. You went astray by your own reasoning, and led others astray by the reasoning of the tyrants. You imagined that the one called to account was someone other than yourselves, and you forgot the word of Allah, glory be to Him:</p>
<p class="ar-block"><span class="ar-inline" dir="rtl" lang="ar">وَلاَ تَرْكَنُوْا إِلَى الذِيْنَ ظَلَمُوْا فَتَمَسَّكُمُ النَّارُ</span></p>
<p>And do not incline toward those who have done wrong, lest the Fire touch you. So you severed what Allah commanded to be joined, and you did it with your eyes open. You spoke of the outward forms of justice while you strayed from its path. You came upon His saying,</p>
<p class="ar-block"><span class="ar-inline" dir="rtl" lang="ar">أَطِيْعُوْا اللهَ وَأَطِيْعُوْا الرَّسُوْلَ وَأُولِي الأَمْرِ مِنْكُمْ</span></p>
<p>Obey Allah, and obey the Messenger and those in authority among you, and you claimed that these powers of darkness were the ones in authority over you — though they disbelieve. And you forgot the word of Allah, exalted is He,</p>
<p class="ar-block"><span class="ar-inline" dir="rtl" lang="ar">قَاتِلُوا الذِيْنَ يَلُونَكُمْ مِنَ الكُفَّار</span></p>
<p>Fight those of the disbelievers who are near you. So you disobeyed the one you were commanded to obey, and obeyed the one you were commanded to fight, all the while reckoning that you did well. Error carried you far, and opinion led you on, until you said that Allah would raise up in your age neither a messenger nor a warner. Is it that the goodness of your deeds has set you beyond all need of Allah''s guardians for the proof? Or that the ugliness of your deeds has cut off your hope of returning to Allah in repentance? Or is it justice that you should pass judgment upon Allah without justice, and be content, on your Messenger''s behalf, with what you would never accept for yourselves in his place? Would any one of you accept that his own child be killed, or that he be driven from his house and his property without right?&quot;</p>
<p>Abu Malik said: &quot;No one would accept that. If any man''s child were killed, or he himself driven from his property, he would be enraged, and his people would be enraged for him, and they would not rest until he was satisfied.&quot;</p>
<p>Salih said: &quot;Then Allah and His Messenger have the greater right that you be enraged at what angers them, when His vicegerent is killed and His guardian is driven from the land.&quot;</p>
<p>Abu Malik said: &quot;It weighs heavily upon us that the guardian of Allah should be killed among us or driven from his land. But they have deliberately kept themselves hidden from us, and the tyrants have gained the upper hand over us.&quot;</p>
<p>Salih said: &quot;Had you supported the guardians of Allah, they would have appeared; had you forsaken His enemies, those enemies would never have prevailed. But the judgment binds you toward the guardians of Allah at three stations. There is the striker set in power, who never tires of the chase and is never satisfied even in triumph. There is the gloating one, well pleased with himself, who bites his fingertips in rage, never slackening in his incitement against their enemy, never heedless of them even when they are heedless of him. And there is the one who hates the deed and holds fast to his love for the guardians of Allah, yet forsakes them all the same — having no clear sight in his faith and no trustworthiness to be relied on in keeping a secret. For this the guardians of Allah have kept themselves hidden from you, by Taqiyya (<span class="ar-inline" dir="rtl" lang="ar">تقيّة</span>), out of caution before you and before this great mass of people who have taken their own desires for their god, flung themselves upon the goods of this world, and helped one another in killing the prophets. They were blind to the fault in their own conduct, so they never called themselves to account for the injustice they did, nor humbled themselves to repent of what they had done. Instead they laid the injustice of their deeds upon Allah and ascribed it to Him, and they said, Allah will raise up, after their messenger, neither a messenger nor a warner. So they made lawful the killing of the guardians of Allah without right. They wronged in the deed, they swerved in the word, and they overstepped in their denial.&quot;</p>
<p>Abu Malik said: &quot;Yes. This is the very likeness of this nation of ours, and this is what they say. Where, then, is the deliverance from it, and where is the escape from the punishment of Allah?&quot;</p>
<p>Salih said: &quot;To Allah. Seek refuge in Him, and He grants you refuge; turn to Him in repentance, and He accepts your repentance; ask Him for the way of His guardians, and by your deeds He delivers you from the deeds of those who have done wrong. And so it is with this mass of people: were they to repent to Allah, He would accept their repentance — and what, then, would Allah gain by punishing them? For Allah does not wrong them by so much as the weight of an atom, even when they are unjust and lie, nor does He rush them to punishment, even when they rush to disobey Him.&quot;</p>
<p>Abu Malik said: &quot;Then I seek refuge from the punishment of Allah by repenting to Him and seeking the means to what pleases Him. Show favor to the one who seeks you, and to the one who asks to be led, by guiding him, and your Lord will reward you.&quot;</p>
<p>Salih said: &quot;If you do this, you will find Allah nearer to pardoning you than you are to repenting to Him, for He loves those who turn to Him. And you will find me eager for your guidance and watchful over you.&quot;</p>
<p>Then Salih''s eyes brimmed with tears at the mention of repentance, and the fullness of his feeling broke off his speech. He gave them heart and bade them go to his father''s house. He went in to his father, the Master who had first sent him out, and took counsel with him over the affair of Abu Malik and his companions.</p>
<p>The Master said: &quot;You know your companions best. If you find good in them, guide them with your guidance; and when you warn them, let no eagerness move you to impose tazir (<span class="ar-inline" dir="rtl" lang="ar">تَعْزِير</span>) upon them. Test them by leaving them to themselves, without harshness, and bid your father be kind to them and deal righteously with them in due season. The man who inclines toward good is not hidden, and Allah will not abandon you behind your back. From the light of His enabling grace He will open for you that by which the affairs of His creation are set in order, and from the gates of guidance that by which He shows you the deeds of the rightly guided.&quot;</p>
<p>He said: So Abu Malik and his companions went back and forth under this testing until their affair was fulfilled and they came to know their own guidance, and the guardian of Allah among them inclined kindly toward guiding them. They gave thanks to Allah for that, and returned to their people as warners, and through them Allah guided a great many of His servants to His religion.</p>
<p>The author said: Whatever in this account took the shape of a story was no idle telling, but a confirmation of what Allah has commanded — for in it lie the steadfastness of the messengers, the signs of the guardians, and the manners of the seekers.</p>
<p>Praise be to Allah, first and last. May Allah bless His Messenger, our master Muhammad, sent forth from Him to His creation as a bearer of good tidings and a warner; and His guardian, the Imam of the God-fearing, the leader of the radiant and honored, the beloved of the Lord of the Worlds; and the Imams from the people of his house, upon whom Allah has bestowed His favor, from whom He has removed all defilement, and whom He has purified completely. Allah is sufficient for us, and how excellent a Trustee, how excellent a Master, and how excellent a Helper. There is no power and no strength except by Allah, the Most High, the Most Great.</p>
<blockquote class="quran aside editorial"><p class="ar" dir="rtl" lang="ar"><strong>Editorial note (tradition-grounded).</strong> In the source''s Arabic the father of this chapter is called &quot;the Shaykh&quot; (<span class="ar-inline" dir="rtl" lang="ar">اَلشَّيْخ</span>), a title the story keeps binding to his advanced years — &quot;the day I grew old,&quot; &quot;your age and your late years.&quot; The word repays a moment''s attention: it grows from a root (sh-y-kh) meaning to grow old and become an elder, and it begins as simply &quot;old man&quot; before ripening into &quot;master,&quot; the one whose accumulated years have become an authority worth following. That double sense sits quietly under the whole exchange. The son honors the aged man who raised him even as he questions the elder''s teaching, and the father''s own anguish — that his son went ahead of him &quot;because of your age&quot; — turns on the gap between the two meanings: an elder in years is not automatically a master in truth. The same title later attaches to Abu Malik, again for the standing his knowledge and forbearance had earned him.</p></blockquote>', 15170);
