INSERT INTO content_unit (slug, bucket, title, kind, sort_order) VALUES ('degrees-of-excellence', 'Islamic', 'Degrees of Excellence', 'book', 0) ON CONFLICT(slug) DO UPDATE SET bucket = excluded.bucket, title = excluded.title;
